INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0001', '3/4 sit-up', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0001-2gPfomN.jpg', 'videos/0001-2gPfomN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0002', '45° side bend', 'waist', 'waist', 'body weight', 'Stand with your feet shoulder-width apart and your arms extended straight down by your sides. Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee. Pause for a moment at the bottom, then slowly return to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia abajo a los lados. Manteniendo la espalda recta y el core activado, flexiona lentamente el torso hacia un lado, bajando la mano hacia la rodilla. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0002-Hy9D21L.jpg', 'videos/0002-Hy9D21L.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0003', 'air bike', 'waist', 'waist', 'body weight', 'Lie flat on your back with your hands placed behind your head. Lift your legs off the ground and bend your knees at a 90-degree angle. Bring your right elbow towards your left knee while simultaneously straightening your right leg. Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg. Continue alternating sides in a pedaling motion for the desired number of repetitions.', 'Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza. Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados. Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha. Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda. Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0003-1ZFqTDN.jpg', 'videos/0003-1ZFqTDN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1512', 'all fours squad stretch', 'upper legs', 'upper legs', 'body weight', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips. Extend one leg straight back, keeping your knee bent and your foot flexed. Slowly lower your hips towards the ground, feeling a stretch in your quads. Hold this position for 20-30 seconds. Switch legs and repeat the stretch on the other side.', 'Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas. Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión. Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps. Mantén esta posición durante 20-30 segundos. Cambia de pierna y repite el estiramiento del otro lado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'quads', 'images/1512-qBcKorM.jpg', 'videos/1512-qBcKorM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0006', 'alternate heel touchers', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms straight out to the sides, parallel to the ground. Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel. Return to the starting position and repeat on the left side, reaching your left hand towards your left heel. Continue alternating sides for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos hacia los lados, paralelos al suelo. Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho. Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0006-qaZVsGk.jpg', 'videos/0006-qaZVsGk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0007', 'alternate lateral pulldown', 'back', 'back', 'cable', 'Sit on the cable machine with your back straight and feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de cable con la espalda recta y los pies apoyados en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Inclínate ligeramente hacia atrás y lleva las agarraderas hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids"]'::jsonb, 'lats', 'images/0007-4IKbhHV.jpg', 'videos/0007-4IKbhHV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1368', 'ankle circles', 'lower legs', 'lower legs', 'body weight', 'Sit on the ground with your legs extended in front of you. Lift one leg off the ground and rotate your ankle in a circular motion. Perform the desired number of circles in one direction, then switch to the other direction. Repeat with the other leg.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Levanta una pierna del suelo y rota el tobillo con un movimiento circular. Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria. Repite con la otra pierna.', 'ankle stabilizers', '["ankle stabilizers"]'::jsonb, 'calves', 'images/1368-uL9CsKm.jpg', 'videos/1368-uL9CsKm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3293', 'archer pull up', 'back', 'back', 'body weight', 'Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight. Continue pulling until your chin is above the bar and your bent arm is fully flexed. Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side. Alternate sides with each repetition.', 'Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto. Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado. Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado. Alterna los lados en cada repetición.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/3293-72BC5Za.jpg', 'videos/3293-72BC5Za.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3294', 'archer push up', 'chest', 'chest', 'body weight', 'Start in a push-up position with your hands slightly wider than shoulder-width apart. Extend one arm straight out to the side, parallel to the ground. Lower your body by bending your elbows, keeping your back straight and core engaged. Push back up to the starting position. Repeat on the other side, extending the opposite arm out to the side. Continue alternating sides for the desired number of repetitions.', 'Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros. Extiende un brazo hacia el lado, paralelo al suelo. Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado. Empuja hacia arriba para volver a la posición inicial. Repite del otro lado, extendiendo el brazo opuesto hacia el lado. Continúa alternando lados durante el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/3294-A9qxk2F.jpg', 'videos/3294-A9qxk2F.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2355', 'arm slingers hanging bent knee legs', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle. Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las rodillas flexionadas formando un ángulo de 90 grados. Activa el core y levanta las rodillas hacia el pecho, acercándolas lo más posible a los codos. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","back"]'::jsonb, 'abs', 'images/2355-uWpxD4v.jpg', 'videos/2355-uWpxD4v.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2333', 'arm slingers hanging straight legs', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your legs straight down. Engage your core and lift your legs up in front of you until they are parallel to the ground. Hold for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas estiradas hacia abajo. Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo. Mantén un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","back"]'::jsonb, 'abs', 'images/2333-PXTIwgu.jpg', 'videos/2333-PXTIwgu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3214', 'arms apart circular toe touch (male)', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and arms extended to the sides. Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand. As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance. Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Manteniendo las piernas rectas, flexiona el torso hacia adelante desde la cintura y lleva la mano derecha hacia los dedos de los pies. Mientras bajas, levanta simultáneamente la pierna izquierda recta detrás de ti, manteniendo el equilibrio. Regresa a la posición inicial y repite el movimiento llevando la mano izquierda hacia los dedos de los pies y levantando la pierna derecha detrás de ti. Continúa alternando lados durante el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","calves"]'::jsonb, 'glutes', 'images/3214-RtyAsy1.jpg', 'videos/3214-RtyAsy1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3204', 'arms overhead full sit-up (male)', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms overhead, keeping them straight. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos por encima de la cabeza, manteniéndolos rectos. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso quede erguido. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/3204-NAkmgdx.jpg', 'videos/3204-NAkmgdx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0009', 'assisted chest dip (kneeling)', 'chest', 'chest', 'leverage machine', 'Adjust the machine to your desired height and secure your knees on the pad. Grasp the handles with your palms facing down and your arms fully extended. Lower your body by bending your elbows until your upper arms are parallel to the floor. Pause for a moment, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla. Agarra las agarraderas con las palmas hacia abajo y los brazos completamente extendidos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa por un momento, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0009-PAgTVaK.jpg', 'videos/0009-PAgTVaK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0011', 'assisted hanging knee raise', 'waist', 'waist', 'assisted', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core muscles and lift your knees towards your chest, bending at the hips and knees. Pause for a moment at the top of the movement, squeezing your abs. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, flexionando las caderas y las rodillas. Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0011-03lzqwk.jpg', 'videos/0011-03lzqwk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0010', 'assisted hanging knee raise with throw down', 'waist', 'waist', 'assisted', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your knees towards your chest, keeping your legs together. Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully. Allow your legs to swing back up and repeat the movement for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas. Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo. Deja que las piernas se balanceen de vuelta hacia arriba y repite el movimiento el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0010-8K0w2yA.jpg', 'videos/0010-8K0w2yA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1708', 'assisted lying calves stretch', 'lower legs', 'lower legs', 'assisted', 'Lie on your back with your legs extended. Bend one knee and place your foot flat on the ground. Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf. Hold the stretch for 20-30 seconds. Release the stretch and repeat on the other leg.', 'Túmbate sobre tu espalda con las piernas extendidas. Flexiona una rodilla y coloca el pie plano sobre el suelo. Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite con la otra pierna.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1708-GxDwDX0.jpg', 'videos/1708-GxDwDX0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1709', 'assisted lying glutes stretch', 'upper legs', 'upper legs', 'assisted', 'Lie on your back with your legs extended. Bend your right knee and place your right ankle on your left thigh, just above the knee. Grasp your left thigh with both hands and gently pull it towards your chest. Hold the stretch for 20-30 seconds. Release and repeat on the other side.', 'Túmbate sobre tu espalda con las piernas extendidas. Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla. Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho. Mantén el estiramiento durante 20-30 segundos. Suelta y repite del otro lado.', 'hamstrings', '["hamstrings"]'::jsonb, 'glutes', 'images/1709-yn0LjwL.jpg', 'videos/1709-yn0LjwL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1710', 'assisted lying gluteus and piriformis stretch', 'upper legs', 'upper legs', 'assisted', 'Lie on your back with your legs extended. Bend your right knee and place your right ankle on your left thigh, just above the knee. Grasp your left thigh with both hands and gently pull it towards your chest. Hold the stretch for 20-30 seconds. Release the stretch and repeat on the other side.', 'Túmbate sobre tu espalda con las piernas extendidas. Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla. Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite del otro lado.', 'hamstrings', '["hamstrings"]'::jsonb, 'glutes', 'images/1710-RQNVT10.jpg', 'videos/1710-RQNVT10.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0012', 'assisted lying leg raise with lateral throw down', 'waist', 'waist', 'assisted', 'Lie flat on your back with your legs extended and your arms by your sides. Place your hands under your glutes for support. Engage your abs and lift your legs off the ground, keeping them straight. While keeping your legs together, lower them to one side until they are a few inches above the ground. Pause for a moment, then lift your legs back to the starting position. Repeat the movement to the other side. Continue alternating sides for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas. Manteniendo las piernas juntas, bájalas hacia un lado hasta que queden a pocos centímetros del suelo. Haz una pausa por un momento, luego levanta las piernas de vuelta a la posición inicial. Repite el movimiento hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors","obliques"]'::jsonb, 'abs', 'images/0012-UGhRD1A.jpg', 'videos/0012-UGhRD1A.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0013', 'assisted lying leg raise with throw down', 'waist', 'waist', 'assisted', 'Lie flat on your back with your legs extended and your arms by your sides. Place your hands under your glutes for support. Engage your core and lift your legs off the ground, keeping them straight. Raise your legs until they are perpendicular to the ground. Lower your legs back down to the starting position. Simultaneously, throw your legs down towards the ground, keeping them straight. Raise your legs back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el core y levanta las piernas del suelo, manteniéndolas rectas. Eleva las piernas hasta que queden perpendiculares al suelo. Baja las piernas de vuelta a la posición inicial. Simultáneamente, lanza las piernas hacia el suelo, manteniéndolas rectas. Eleva las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","quadriceps"]'::jsonb, 'abs', 'images/0013-VX5YKR5.jpg', 'videos/0013-VX5YKR5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0014', 'assisted motion russian twist', 'waist', 'waist', 'medicine ball', 'Sit on the ground with your knees bent and feet flat on the floor. Hold the medicine ball with both hands in front of your chest. Lean back slightly, engaging your abs and keeping your back straight. Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body. Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body. Continue alternating sides for the desired number of repetitions.', 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Sostén el balón medicinal con ambas manos frente al pecho. Inclínate ligeramente hacia atrás, activando el abdomen y manteniendo la espalda recta. Gira lentamente el torso hacia la derecha, llevando el balón medicinal hacia el lado derecho del cuerpo. Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando el balón medicinal hacia el lado izquierdo del cuerpo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0014-r7cT9YD.jpg', 'videos/0014-r7cT9YD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0015', 'assisted parallel close grip pull-up', 'back', 'back', 'leverage machine', 'Adjust the machine to your desired weight and height. Place your hands on the parallel bars with a close grip, palms facing each other. Hang from the bars with your arms fully extended and your feet off the ground. Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body. Continue pulling until your chin is above the bars. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina al peso y la altura deseados. Coloca las manos en las barras paralelas con un agarre cerrado, con las palmas mirándose entre sí. Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el suelo. Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las barras, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de las barras. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0015-vrhHa6D.jpg', 'videos/0015-vrhHa6D.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0016', 'assisted prone hamstring', 'upper legs', 'upper legs', 'assisted', 'Lie face down on a mat or bench with your legs fully extended. Have a partner or use a resistance band to secure your ankles. Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo sobre una esterilla o un banco con las piernas completamente extendidas. Pide a un compañero o usa una banda elástica para sujetar tus tobillos. Activa los isquiotibiales y levanta las piernas hacia los glúteos, manteniendo las rodillas rectas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","lower back"]'::jsonb, 'hamstrings', 'images/0016-VedGSby.jpg', 'videos/0016-VedGSby.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1713', 'assisted prone lying quads stretch', 'upper legs', 'upper legs', 'assisted', 'Lie face down on the ground with your legs extended. Bend your left knee and reach back with your left hand to grab your left foot or ankle. Gently pull your left foot towards your glutes, feeling a stretch in your left quad. Hold the stretch for 20-30 seconds, then release. Repeat with your right leg.', 'Túmbate boca abajo en el suelo con las piernas extendidas. Flexiona la rodilla izquierda y lleva la mano izquierda hacia atrás para agarrar el pie o el tobillo izquierdo. Jala suavemente el pie izquierdo hacia los glúteos, sintiendo un estiramiento en el cuádriceps izquierdo. Mantén el estiramiento durante 20-30 segundos, luego suelta. Repite con la pierna derecha.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'quads', 'images/1713-YUYAMEj.jpg', 'videos/1713-YUYAMEj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1714', 'assisted prone rectus femoris stretch', 'waist', 'waist', 'assisted', 'Lie face down on the ground with your legs straight. Bend your right knee and reach back with your right hand to grab your right foot or ankle. Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh. Hold the stretch for 20-30 seconds. Release and repeat on the other side.', 'Túmbate boca abajo en el suelo con las piernas rectas. Flexiona la rodilla derecha y lleva la mano derecha hacia atrás para agarrar el pie o el tobillo derecho. Jala suavemente el pie o el tobillo derecho hacia los glúteos, sintiendo un estiramiento en la parte frontal del muslo derecho. Mantén el estiramiento durante 20-30 segundos. Suelta y repite del otro lado.', 'quadriceps', '["quadriceps"]'::jsonb, 'abs', 'images/1714-2Ryn564.jpg', 'videos/1714-2Ryn564.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0017', 'assisted pull-up', 'back', 'back', 'leverage machine', 'Adjust the machine to your desired weight and height settings. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your feet off the ground. Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body. Continue pulling until your chin is above the handles. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina a los valores de peso y altura deseados. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo. Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de las agarraderas. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0017-kiJ4Z2K.jpg', 'videos/0017-kiJ4Z2K.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1716', 'assisted seated pectoralis major stretch with stability ball', 'chest', 'chest', 'assisted', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a stability ball with both hands and extend your arms straight out in front of you. Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles. Hold the stretch for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti. Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1716-RoV1Rfa.jpg', 'videos/1716-RoV1Rfa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1712', 'assisted side lying adductor stretch', 'upper legs', 'upper legs', 'assisted', 'Lie on your side with your legs straight and stacked on top of each other. Bend your bottom leg slightly for stability. Place your top foot on a stable surface, such as a bench or step. Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh. Hold the stretch for 20-30 seconds. Return to the starting position and repeat on the other side.', 'Túmbate de lado con las piernas rectas y apiladas una sobre la otra. Flexiona ligeramente la pierna de abajo para mayor estabilidad. Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón. Manteniendo la pierna de arriba recta, bájala lentamente hacia el suelo, sintiendo un estiramiento en la parte interna del muslo. Mantén el estiramiento durante 20-30 segundos. Regresa a la posición inicial y repite del otro lado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'adductors', 'images/1712-hC6oYY5.jpg', 'videos/1712-hC6oYY5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1758', 'assisted sit-up', 'waist', 'waist', 'assisted', 'Sit on the edge of a bench or have someone hold your feet down. Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco o pide a alguien que te sujete los pies. Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/1758-aumB2IV.jpg', 'videos/1758-aumB2IV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1431', 'assisted standing chin-up', 'back', 'back', 'leverage machine', 'Adjust the machine to your desired assistance level. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your chest up and shoulders back, engage your core, and slightly bend your knees. Pull your body up by flexing your elbows and driving your elbows down towards your sides. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina al nivel de asistencia deseado. Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén el pecho arriba y los hombros atrás, activa el core y flexiona ligeramente las rodillas. Levanta el cuerpo flexionando los codos y llevándolos hacia abajo, en dirección a los costados. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/1431-7OeHptV.jpg', 'videos/1431-7OeHptV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1432', 'assisted standing pull-up', 'back', 'back', 'leverage machine', 'Adjust the machine to your desired weight and height settings. Stand facing the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Engage your lats and biceps, and pull yourself up towards the handles. Pause for a moment at the top, squeezing your back muscles. Slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina a los valores de peso y altura deseados. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Activa los dorsales y los bíceps, y levántate hacia las agarraderas. Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda. Bájate lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/1432-f4xtKBj.jpg', 'videos/1432-f4xtKBj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0018', 'assisted standing triceps extension (with towel)', 'upper arms', 'upper arms', 'assisted', 'Stand with your feet shoulder-width apart and hold a towel with both hands behind your head. Keep your elbows close to your ears and your upper arms stationary. Slowly extend your forearms upward, squeezing your triceps at the top. Pause for a moment, then slowly lower the towel back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza. Mantén los codos cerca de las orejas y la parte superior de los brazos quieta. Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior. Haz una pausa por un momento, luego baja lentamente la toalla de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0018-7HcfMBP.jpg', 'videos/0018-7HcfMBP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0019', 'assisted triceps dip (kneeling)', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the machine to your desired weight and height. Kneel down on the pad facing the machine, with your hands gripping the handles. Lower your body by bending your elbows, keeping your back straight and close to the machine. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina al peso y la altura deseados. Arrodíllate sobre la almohadilla frente a la máquina, con las manos sujetando las agarraderas. Baja el cuerpo flexionando los codos, manteniendo la espalda recta y cerca de la máquina. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0019-J60bN17.jpg', 'videos/0019-J60bN17.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2364', 'assisted wide-grip chest dip (kneeling)', 'chest', 'chest', 'leverage machine', 'Adjust the machine to your desired height and secure your knees on the pad. Grasp the handles with a wide grip and keep your elbows slightly bent. Lower your body by bending your elbows until your upper arms are parallel to the floor. Push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla. Agarra las agarraderas con un agarre amplio y mantén los codos ligeramente flexionados. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/2364-PnZJIrk.jpg', 'videos/2364-PnZJIrk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3220', 'astride jumps (male)', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Jump explosively upwards, extending your legs and arms. While in the air, spread your legs apart and bring your arms out to the sides. Land softly with your feet shoulder-width apart, bending your knees to absorb the impact. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Salta explosivamente hacia arriba, extendiendo las piernas y los brazos. Mientras estás en el aire, separa las piernas y lleva los brazos hacia los lados. Aterriza suavemente con los pies separados a la altura de los hombros, flexionando las rodillas para absorber el impacto. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/3220-f9lVSSI.jpg', 'videos/3220-f9lVSSI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3672', 'back and forth step', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart. Step forward with your right foot, bending your knee and lowering your body into a lunge position. Push off with your right foot and step back to the starting position. Repeat the movement with your left foot, alternating legs with each step. Continue stepping back and forth, maintaining a steady pace. Repeat for the desired duration or number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada. Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial. Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso. Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante. Repite durante la duración o el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","glutes","calves"]'::jsonb, 'cardiovascular system', 'images/3672-fNGumX0.jpg', 'videos/3672-fNGumX0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1314', 'back extension on exercise ball', 'back', 'back', 'stability ball', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface. Position your hands behind your head or crossed over your chest. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/1314-qLpO4vV.jpg', 'videos/1314-qLpO4vV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3297', 'back lever', 'back', 'back', 'body weight', 'Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. Bend your knees and tuck them towards your chest. Slowly lift your legs up, keeping them straight, until your body is parallel to the ground. Hold this position for a few seconds, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Flexiona las rodillas y llévalas hacia el pecho. Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo. Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms","core"]'::jsonb, 'upper back', 'images/3297-GaSzzuh.jpg', 'videos/3297-GaSzzuh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1405', 'back pec stretch', 'back', 'back', 'body weight', 'Stand tall with your feet shoulder-width apart. Extend your arms straight out in front of you, parallel to the ground. Cross your arms in front of your body, with your right arm over your left arm. Interlock your fingers and rotate your palms away from your body. Slowly raise your arms up and away from your body, feeling a stretch in your back and chest. Hold the stretch for 15-30 seconds, then release. Repeat on the opposite side.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos rectos frente a ti, paralelos al suelo. Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo. Entrelaza los dedos y gira las palmas alejándolas del cuerpo. Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del lado opuesto.', 'shoulders', '["shoulders","chest"]'::jsonb, 'lats', 'images/1405-chfnQnM.jpg', 'videos/1405-chfnQnM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1473', 'backward jump', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Bend your knees slightly and jump backwards, pushing off with both feet. Land softly on the balls of your feet, bending your knees to absorb the impact. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies. Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes","calves"]'::jsonb, 'quads', 'images/1473-SaDOwk7.jpg', 'videos/1473-SaDOwk7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0020', 'balance board', 'upper legs', 'upper legs', 'body weight', 'Place the balance board on a flat surface. Step onto the balance board with one foot, ensuring it is centered. Slowly shift your weight onto the foot on the balance board, keeping your core engaged. Maintain your balance and stability as you hold the position for a desired amount of time. Repeat the exercise with the other foot.', 'Coloca la tabla de equilibrio sobre una superficie plana. Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado. Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado. Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado. Repite el ejercicio con el otro pie.', 'calves', '["calves","hamstrings","glutes"]'::jsonb, 'quads', 'images/0020-xAySMB0.jpg', 'videos/0020-xAySMB0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0968', 'band alternating biceps curl', 'upper arms', 'upper arms', 'band', 'Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up. Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top. Lower the arm back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca de los costados y flexiona lentamente un brazo hacia el hombro, apretando el bíceps en la parte superior. Baja el brazo de vuelta a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0968-3omWx6P.jpg', 'videos/0968-3omWx6P.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0969', 'band alternating v-up', 'waist', 'waist', 'band', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band. Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes. As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other. Repeat the movement, alternating the position of your legs with each repetition. Continue for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda. Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies. Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra. Repite el movimiento, alternando la posición de las piernas en cada repetición. Continúa durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0969-ztAa1RK.jpg', 'videos/0969-ztAa1RK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0970', 'band assisted pull-up', 'back', 'back', 'band', 'Attach the band to a pull-up bar or sturdy anchor point. Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart. Hang with your arms fully extended, keeping your core engaged and your shoulders down and back. Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips. Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la banda a una barra de dominadas o a un punto de anclaje resistente. Pisa la banda y agarra la barra con las palmas mirando hacia afuera, con las manos un poco más separadas que el ancho de los hombros. Cuélgate con los brazos completamente extendidos, manteniendo el core activado y los hombros abajo y atrás. Sube el cuerpo hacia la barra juntando los omóplatos y llevando los codos hacia abajo, en dirección a las caderas. Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0970-r1XNRYB.jpg', 'videos/0970-r1XNRYB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0971', 'band assisted wheel rollerout', 'waist', 'waist', 'band', 'Kneel on the floor and hold the handles of the band with both hands, palms facing down. Place the band on the ground in front of you and position your hands shoulder-width apart. Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control. Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position. Repeat for the desired number of repetitions.', 'Arrodíllate en el suelo y sostén las agarraderas de la banda con ambas manos, con las palmas hacia abajo. Coloca la banda en el suelo frente a ti y posiciona las manos separadas a la altura de los hombros. Activa el core y rueda lentamente la rueda hacia adelante, extendiendo el cuerpo lo más que puedas mientras mantienes el control. Haz una pausa por un momento en el punto más lejano, luego rueda lentamente la rueda de vuelta hacia las rodillas para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'lower back', '["lower back"]'::jsonb, 'abs', 'images/0971-zhF9lW4.jpg', 'videos/0971-zhF9lW4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1254', 'band bench press', 'chest', 'chest', 'band', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart. Extend your arms fully, pushing the bands away from your chest. Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros. Extiende los brazos por completo, empujando las bandas alejándolas del pecho. Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1254-khlHMqs.jpg', 'videos/1254-khlHMqs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0980', 'band bent-over hip extension', 'upper legs', 'upper legs', 'band', 'Attach the band to a sturdy anchor point at ankle height. Stand facing away from the anchor point with your feet shoulder-width apart. Step back to create tension in the band, keeping your knees slightly bent. Hinge at the hips and lean forward, maintaining a neutral spine. Extend your right leg straight back, squeezing your glutes at the top. Lower your right leg back down and repeat with the left leg. Continue alternating legs for the desired number of repetitions.', 'Sujeta la banda a un punto de anclaje resistente a la altura del tobillo. Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros. Da un paso atrás para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas. Flexiona las caderas e inclínate hacia adelante, manteniendo la columna en posición neutral. Extiende la pierna derecha recta hacia atrás, apretando los glúteos en la parte superior. Baja la pierna derecha de vuelta y repite con la pierna izquierda. Continúa alternando las piernas durante el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0980-wSScovH.jpg', 'videos/0980-wSScovH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0972', 'band bicycle crunch', 'waist', 'waist', 'band', 'Lie flat on your back with your hands behind your head and your knees bent. Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee. Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee. Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas. Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha. Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda. Continúa alternando el movimiento de giro, como si estuvieras pedaleando una bicicleta, manteniendo el core activado durante todo el movimiento. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","obliques"]'::jsonb, 'abs', 'images/0972-tZkGYZ9.jpg', 'videos/0972-tZkGYZ9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0974', 'band close-grip pulldown', 'back', 'back', 'band', 'Attach the band to a high anchor point, such as a pull-up bar or sturdy beam. Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart. Step back to create tension in the band, keeping your feet hip-width apart. Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente. Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros. Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas. Activa el core y mantén la espalda recta mientras tiras de la banda hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte inferior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0974-DptumMx.jpg', 'videos/0974-DptumMx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0975', 'band close-grip push-up', 'upper arms', 'upper arms', 'band', 'Place a band around your upper arms, just above the elbows. Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels. Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Coloca una banda alrededor de la parte superior de los brazos, justo por encima de los codos. Adopta una posición de flexión de brazos con las manos justo debajo de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Flexiona los codos y baja el pecho hacia el suelo, manteniendo los codos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0975-ufaxB52.jpg', 'videos/0975-ufaxB52.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0976', 'band concentration curl', 'upper arms', 'upper arms', 'band', 'Sit on a bench or chair with your legs spread apart and your feet flat on the ground. Hold one end of the band in your hand and step on the other end with your foot on the same side. Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee. With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary. Pause for a moment at the top, then slowly lower your hand back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Siéntate en un banco o silla con las piernas separadas y los pies apoyados en el suelo. Sostén un extremo de la banda en la mano y pisa el otro extremo con el pie del mismo lado. Inclínate ligeramente hacia adelante y apoya el codo en la parte interna del muslo, justo encima de la rodilla. Con la palma hacia arriba, flexiona lentamente la mano hacia el hombro, manteniendo quieta la parte superior del brazo. Haz una pausa por un momento en la parte superior, luego baja lentamente la mano de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0976-kmVVAfu.jpg', 'videos/0976-kmVVAfu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3117', 'band fixed back close grip pulldown', 'back', 'back', 'band', 'Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam. Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent. Grasp the band with a close grip, palms facing towards you. Keep your back straight and engage your core. Pull the band down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, feeling the contraction in your lats. Slowly release the band back to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions.', 'Sujeta la banda a un punto fijo por encima de ti, como una barra de dominadas o una viga resistente. Siéntate en un banco o silla frente a la banda, con los pies apoyados en el suelo y las rodillas flexionadas. Agarra la banda con un agarre cerrado, con las palmas hacia ti. Mantén la espalda recta y activa el core. Tira de la banda hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales. Suelta lentamente la banda de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/3117-4LoWllp.jpg', 'videos/3117-4LoWllp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3116', 'band fixed back underhand pulldown', 'back', 'back', 'band', 'Attach the band to a sturdy anchor point above your head. Stand facing the anchor point with your feet shoulder-width apart. Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart. Step back to create tension in the band, keeping your arms fully extended. Engage your core and squeeze your shoulder blades together. Pull the band down towards your chest, leading with your elbows. Pause for a moment at the bottom of the movement, feeling the contraction in your lats. Slowly release the tension in the band and return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Da un paso atrás para generar tensión en la banda, manteniendo los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de la banda hacia el pecho, guiando el movimiento con los codos. Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales. Suelta lentamente la tensión de la banda y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/3116-ZH68exZ.jpg', 'videos/3116-ZH68exZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0977', 'band front lateral raise', 'shoulders', 'shoulders', 'band', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down. Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground. Pause for a moment at the top, then slowly lower the band back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo. Mantén los brazos rectos y levanta la banda frente a ti hasta que los brazos queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","upper back"]'::jsonb, 'delts', 'images/0977-sTg7iys.jpg', 'videos/0977-sTg7iys.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0978', 'band front raise', 'shoulders', 'shoulders', 'band', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down. Keep your arms straight and slowly raise them forward until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo. Mantén los brazos rectos y levántalos lentamente hacia adelante hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0978-TFA88iB.jpg', 'videos/0978-TFA88iB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1408', 'band hip lift', 'upper legs', 'upper legs', 'band', 'Lie on your back with your knees bent and feet flat on the ground. Place a resistance band just above your knees. Engage your glutes and core muscles. Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca una banda elástica justo por encima de las rodillas. Activa los glúteos y los músculos del core. Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/1408-E4R8Hz1.jpg', 'videos/1408-E4R8Hz1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0979', 'band horizontal pallof press', 'waist', 'waist', 'band', 'Attach the band to a sturdy anchor point at waist height. Stand perpendicular to the anchor point with your feet shoulder-width apart. Grasp the band handle with both hands and step away from the anchor point to create tension in the band. Bring your hands to your chest, keeping your elbows bent and close to your body. Engage your core and maintain a stable stance. Extend your arms straight out in front of you, pushing the band away from your body. Hold the extended position for a few seconds, focusing on maintaining tension in your core. Slowly bring your hands back to your chest, resisting the pull of the band. Repeat for the desired number of repetitions.', 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Ponte de pie perpendicular al punto de anclaje con los pies separados a la altura de los hombros. Agarra la agarradera de la banda con ambas manos y aléjate del punto de anclaje para generar tensión en la banda. Lleva las manos hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo. Activa el core y mantén una postura estable. Extiende los brazos rectos frente a ti, empujando la banda alejándola del cuerpo. Mantén la posición extendida durante unos segundos, enfocándote en mantener la tensión en el core. Lleva lentamente las manos de vuelta al pecho, resistiendo el tirón de la banda. Repite el número de repeticiones deseado.', 'obliques', '["obliques","glutes"]'::jsonb, 'abs', 'images/0979-9pa4H5m.jpg', 'videos/0979-9pa4H5m.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0981', 'band jack knife sit-up', 'waist', 'waist', 'band', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band. Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda. Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0981-KCBKjma.jpg', 'videos/0981-KCBKjma.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0983', 'band kneeling one arm pulldown', 'back', 'back', 'band', 'Attach the band to a sturdy anchor point above your head. Kneel down and hold the band with one hand, palm facing down. Extend your arm fully overhead, keeping your elbow slightly bent. Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage. Pause for a moment at the bottom, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza. Arrodíllate y sostén la banda con una mano, con la palma hacia abajo. Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado. Activa los dorsales y tira de la banda hacia el costado, llevando el codo hacia las costillas. Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'biceps', '["biceps","rhomboids"]'::jsonb, 'lats', 'images/0983-pmnrOp0.jpg', 'videos/0983-pmnrOp0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0985', 'band kneeling twisting crunch', 'waist', 'waist', 'band', 'Attach the band to a sturdy anchor point at waist height. Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides. Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip. Pause for a moment, then slowly return to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Arrodíllate de espaldas al punto de anclaje y sostén la banda con ambas manos, manteniendo los codos flexionados y cerca de los costados. Activa el abdomen y gira lentamente el torso hacia un lado, llevando las manos hacia la cadera opuesta. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0985-225x2Vd.jpg', 'videos/0985-225x2Vd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0984', 'band lying hip internal rotation', 'upper legs', 'upper legs', 'band', 'Lie on your back with your legs straight and a resistance band looped around your feet. Bend your knees and bring them towards your chest, keeping your feet together. Slowly rotate your knees outwards, away from each other, while keeping your feet together. Pause for a moment at the end of the rotation, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas rectas y una banda elástica enrollada alrededor de los pies. Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies juntos. Rota lentamente las rodillas hacia afuera, separándolas entre sí, mientras mantienes los pies juntos. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/0984-vIICElP.jpg', 'videos/0984-vIICElP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1002', 'band lying straight leg raise', 'waist', 'waist', 'band', 'Lie flat on your back with your legs straight and your feet together. Place the band around the arches of your feet and hold the ends of the band with your hands. Engaging your abs, lift both legs off the ground until they are perpendicular to the floor. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas rectas y los pies juntos. Coloca la banda alrededor de los arcos de los pies y sostén los extremos de la banda con las manos. Activando el abdomen, levanta ambas piernas del suelo hasta que queden perpendiculares al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/1002-bbLR7fB.jpg', 'videos/1002-bbLR7fB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0986', 'band one arm overhead biceps curl', 'upper arms', 'upper arms', 'band', 'Stand with your feet shoulder-width apart and place one end of the band under your foot. Hold the other end of the band with your arm fully extended overhead, palm facing forward. Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps. Pause for a moment at the top, then slowly lower your forearm back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca un extremo de la banda bajo el pie. Sostén el otro extremo de la banda con el brazo completamente extendido por encima de la cabeza, con la palma hacia adelante. Manteniendo quieta la parte superior del brazo, flexiona el antebrazo hacia el hombro, apretando el bíceps. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/0986-UNAB8ak.jpg', 'videos/0986-UNAB8ak.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0987', 'band one arm single leg split squat', 'upper legs', 'upper legs', 'band', 'Stand with your feet hip-width apart and place a resistance band around your ankles. Extend one leg forward and rest the top of your foot on a bench or step behind you. Hold onto a support with one hand for balance. Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes. Push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos. Extiende una pierna hacia adelante y apoya la parte superior del pie sobre un banco o escalón detrás de ti. Sujétate de un apoyo con una mano para mantener el equilibrio. Flexiona la pierna de apoyo y baja el cuerpo hacia una posición de sentadilla, manteniendo la rodilla alineada con los dedos del pie. Empuja con el talón para regresar a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'quads', 'images/0987-arsYEd3.jpg', 'videos/0987-arsYEd3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0988', 'band one arm standing low row', 'back', 'back', 'band', 'Attach the band to a stable anchor point at waist height. Stand facing the anchor point with your feet shoulder-width apart. Hold the band with one hand, palm facing inward, and step back to create tension in the band. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pull the band towards your waist, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the band back to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Sujeta la banda a un punto de anclaje estable a la altura de la cintura. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Sostén la banda con una mano, con la palma hacia adentro, y da un paso atrás para generar tensión en la banda. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Tira de la banda hacia la cintura, juntando los omóplatos. Haz una pausa por un momento en la parte superior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/0988-km0sQC0.jpg', 'videos/0988-km0sQC0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0989', 'band one arm twisting chest press', 'chest', 'chest', 'band', 'Attach the band to a sturdy anchor point at chest height. Stand with your side facing the anchor point and grab the band with one hand. Step away from the anchor point to create tension in the band. Position your feet shoulder-width apart and slightly bend your knees. Bring your hand holding the band across your body, towards the opposite shoulder. While maintaining tension in the band, push your hand forward and away from your body, extending your arm. Slowly return to the starting position and repeat for the desired number of repetitions. Switch sides and repeat the exercise with the other hand.', 'Sujeta la banda a un punto de anclaje resistente a la altura del pecho. Ponte de pie con el costado hacia el punto de anclaje y agarra la banda con una mano. Aléjate del punto de anclaje para generar tensión en la banda. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Lleva la mano que sostiene la banda a través del cuerpo, hacia el hombro opuesto. Manteniendo la tensión en la banda, empuja la mano hacia adelante y alejándola del cuerpo, extendiendo el brazo. Regresa lentamente a la posición inicial y repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con la otra mano.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0989-c16nYGA.jpg', 'videos/0989-c16nYGA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0990', 'band one arm twisting seated row', 'back', 'back', 'band', 'Sit on a bench or chair with your feet flat on the ground and your back straight. Hold the band with one hand and extend your arm fully in front of you. Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together. At the same time, twist your torso towards the side of the pulling arm. Pause for a moment at the top, then slowly release the tension in the band and return to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta. Sostén la banda con una mano y extiende el brazo completamente frente a ti. Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos. Al mismo tiempo, gira el torso hacia el lado del brazo que tira. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión de la banda y regresa a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/0990-DKBwJrL.jpg', 'videos/0990-DKBwJrL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0991', 'band pull through', 'upper legs', 'upper legs', 'band', 'Attach a resistance band to a sturdy anchor point at ground level. Stand facing away from the anchor point with your feet shoulder-width apart. Step forward to create tension in the band, keeping your knees slightly bent. Hinge at the hips and push your glutes back, maintaining a slight bend in your knees. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Drive your hips forward and squeeze your glutes to return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una banda elástica a un punto de anclaje resistente a nivel del suelo. Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros. Da un paso adelante para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas. Flexiona las caderas y lleva los glúteos hacia atrás, manteniendo una ligera flexión en las rodillas. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Empuja las caderas hacia adelante y aprieta los glúteos para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0991-VtTbiP3.jpg', 'videos/0991-VtTbiP3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0992', 'band push sit-up', 'waist', 'waist', 'band', 'Attach the band securely to a stable anchor point. Lie flat on your back with your knees bent and feet flat on the ground. Hold the band with both hands and extend your arms straight up towards the ceiling. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la banda de forma segura a un punto de anclaje estable. Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Sostén la banda con ambas manos y extiende los brazos rectos hacia el techo. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest"]'::jsonb, 'abs', 'images/0992-zFzbBfL.jpg', 'videos/0992-zFzbBfL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0993', 'band reverse fly', 'shoulders', 'shoulders', 'band', 'Attach the band to a stationary object at chest height. Stand with your feet shoulder-width apart and hold the band with both hands in front of you. Keep your arms straight and lift them out to the sides until they are parallel to the ground. Squeeze your shoulder blades together at the top of the movement. Slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la banda a un objeto fijo a la altura del pecho. Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti. Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo. Junta los omóplatos en la parte superior del movimiento. Baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'upper back', '["upper back","trapezius"]'::jsonb, 'delts', 'images/0993-sTfvVsG.jpg', 'videos/0993-sTfvVsG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0994', 'band reverse wrist curl', 'lower arms', 'lower arms', 'band', 'Sit on a bench or chair with your feet flat on the ground. Hold the band with an overhand grip, palms facing down, and wrap it around your fingers. Rest your forearms on your thighs, with your wrists hanging off the edge. Slowly curl your wrists upward, squeezing your forearms. Pause for a moment at the top, then slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén la banda con un agarre prono, con las palmas hacia abajo, y envuélvela alrededor de los dedos. Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos. Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'forearms', 'images/0994-Ezpnw9d.jpg', 'videos/0994-Ezpnw9d.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0996', 'band seated hip internal rotation', 'upper legs', 'upper legs', 'band', 'Sit on a chair or bench with your back straight and feet flat on the ground. Place a resistance band around your thighs, just above your knees. Keep your knees bent at a 90-degree angle and your feet shoulder-width apart. Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Coloca una banda elástica alrededor de los muslos, justo por encima de las rodillas. Mantén las rodillas flexionadas formando un ángulo de 90 grados y los pies separados a la altura de los hombros. Activa los glúteos y rota lentamente las rodillas hacia afuera, empujando contra la resistencia de la banda. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/0996-9gbyYKk.jpg', 'videos/0996-9gbyYKk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1011', 'band seated twist', 'waist', 'waist', 'band', 'Sit on the ground with your legs extended in front of you and your back straight. Wrap the band around your waist and hold the ends with both hands. Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground. Pause for a moment at the end of the twist, then slowly return to the starting position. Repeat the twist to the other side. Continue alternating sides for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas frente a ti y la espalda recta. Envuelve la banda alrededor de la cintura y sostén los extremos con ambas manos. Activa el abdomen y gira lentamente el torso hacia un lado, manteniendo la espalda recta y los pies en el suelo. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/1011-S1JXDAG.jpg', 'videos/1011-S1JXDAG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0997', 'band shoulder press', 'shoulders', 'shoulders', 'band', 'Stand with your feet shoulder-width apart and place the band under your feet. Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent. Press the band overhead, fully extending your arms. Pause for a moment at the top, then slowly lower the band back to shoulder height. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies. Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados. Empuja la banda por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0997-peAeMR3.jpg', 'videos/0997-peAeMR3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1018', 'band shrug', 'back', 'back', 'band', 'Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands. Keep your arms straight and relaxed, and let the band hang in front of your thighs. Engage your traps by shrugging your shoulders upward, lifting the band as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos. Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos. Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'traps', 'images/1018-trmte8s.jpg', 'videos/1018-trmte8s.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0998', 'band side triceps extension', 'upper arms', 'upper arms', 'band', 'Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down. Extend your arms straight out to the sides, keeping them parallel to the ground. Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still. Pause for a moment, then slowly extend your arms back out to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos, con las palmas hacia abajo. Extiende los brazos hacia los lados, manteniéndolos paralelos al suelo. Flexiona lentamente los codos y lleva las manos hacia los hombros, manteniendo quieta la parte superior de los brazos. Haz una pausa por un momento, luego extiende lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0998-obe5LMq.jpg', 'videos/0998-obe5LMq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0999', 'band single leg calf raise', 'lower legs', 'lower legs', 'band', 'Stand with your feet hip-width apart and place the band around the ball of your left foot. Hold onto a stable object for balance if needed. Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot. Pause for a moment at the top, then slowly lower your left heel back down to the starting position. Repeat for the desired number of repetitions, then switch to the right leg.', 'Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie izquierdo. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Levanta lentamente el talón izquierdo del suelo, llevando el peso del cuerpo hacia la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón izquierdo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la pierna derecha.', 'ankles', '["ankles","feet"]'::jsonb, 'calves', 'images/0999-9JprnPh.jpg', 'videos/0999-9JprnPh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1000', 'band single leg reverse calf raise', 'lower legs', 'lower legs', 'band', 'Stand with your feet hip-width apart and place the band around the ball of your foot. Hold onto a stable object for balance. Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch to the other leg.', 'Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie. Sujétate de un objeto estable para mantener el equilibrio. Levanta lentamente el talón del suelo, llevando el peso del cuerpo hacia la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1000-QsSQWbf.jpg', 'videos/1000-QsSQWbf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1001', 'band single leg split squat', 'upper legs', 'upper legs', 'band', 'Stand with your feet hip-width apart and place a resistance band around your ankles. Take a big step forward with your right foot and a smaller step back with your left foot. Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground. Push through your right heel to return to the starting position. Repeat on the other side.', 'Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos. Da un paso grande hacia adelante con el pie derecho y un paso más pequeño hacia atrás con el pie izquierdo. Flexiona las rodillas y baja el cuerpo hasta que el muslo derecho quede paralelo al suelo, manteniendo la rodilla izquierda ligeramente por encima del suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite del otro lado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'quads', 'images/1001-y8bYM8w.jpg', 'videos/1001-y8bYM8w.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1004', 'band squat', 'upper legs', 'upper legs', 'band', 'Stand with your feet shoulder-width apart, with the band placed just above your knees. Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position. Make sure your knees are tracking over your toes and your weight is in your heels. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con la banda colocada justo por encima de las rodillas. Manteniendo el pecho arriba y el core activado, lleva las caderas hacia atrás y flexiona las rodillas para bajar a una posición de sentadilla. Asegúrate de que las rodillas se alineen con los dedos de los pies y de que el peso recaiga en los talones. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1004-TUZLh71.jpg', 'videos/1004-TUZLh71.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1003', 'band squat row', 'upper legs', 'upper legs', 'band', 'Attach the band to a sturdy anchor point at waist height. Stand facing the anchor point with your feet shoulder-width apart. Hold the band handles with your palms facing each other and your arms extended in front of you. Bend your knees and lower into a squat position, keeping your back straight and chest lifted. From the squat position, pull the band handles towards your body, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti. Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","back"]'::jsonb, 'glutes', 'images/1003-w1NOByi.jpg', 'videos/1003-w1NOByi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1005', 'band standing crunch', 'waist', 'waist', 'band', 'Attach the band to a sturdy anchor point at waist height. Stand facing away from the anchor point with your feet shoulder-width apart. Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body. Engage your abs and slowly crunch forward, bringing your chest towards your knees. Pause for a moment at the top of the crunch, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros. Sostén la banda con ambas manos y llévala hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo. Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/1005-Kzg30R7.jpg', 'videos/1005-Kzg30R7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1022', 'band standing rear delt row', 'shoulders', 'shoulders', 'band', 'Stand with your feet shoulder-width apart and place the band under your feet. Hold the band handles with your palms facing each other and your arms extended in front of you. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pull the band towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies. Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Tira de la banda hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids","biceps"]'::jsonb, 'delts', 'images/1022-tc5dYrf.jpg', 'videos/1022-tc5dYrf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1007', 'band standing twisting crunch', 'waist', 'waist', 'band', 'Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest. Hold the ends of the band with your hands, keeping your elbows bent and close to your sides. Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee. Pause for a moment, then return to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de la espalda, cruzándola frente al pecho. Sujeta los extremos de la banda con las manos, manteniendo los codos flexionados y cerca de los costados. Activa el abdomen y gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta. Haz una pausa breve y luego vuelve a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/1007-euq4pwp.jpg', 'videos/1007-euq4pwp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1008', 'band step-up', 'upper legs', 'upper legs', 'band', 'Place a band around your thighs, just above your knees. Stand facing a step or platform with your feet hip-width apart. Step up onto the platform with your right foot, pushing through your heel. Extend your left leg behind you, keeping it straight. Lower your left foot back down to the ground. Repeat with your left foot stepping up onto the platform. Continue alternating legs for the desired number of repetitions.', 'Coloca una banda alrededor de los muslos, justo por encima de las rodillas. Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas. Sube a la plataforma con el pie derecho, empujando con el talón. Extiende la pierna izquierda hacia atrás, manteniéndola recta. Baja el pie izquierdo de nuevo hasta el suelo. Repite subiendo a la plataforma con el pie izquierdo. Continúa alternando las piernas durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1008-d5bTEPV.jpg', 'videos/1008-d5bTEPV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1009', 'band stiff leg deadlift', 'upper legs', 'upper legs', 'band', 'Stand with your feet shoulder-width apart and place the band around your ankles. Hold the band with both hands in front of your thighs, palms facing your body. Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground. As you lower, push your hips back and allow your knees to bend slightly. Lower the band towards the ground, feeling a stretch in your hamstrings. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los tobillos. Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo. Manteniendo la espalda recta y el core activado, flexiona las caderas y baja lentamente la parte superior del cuerpo hacia el suelo. Mientras bajas, empuja las caderas hacia atrás y deja que las rodillas se flexionen ligeramente. Baja la banda hacia el suelo, sintiendo un estiramiento en los isquiotibiales. Haz una pausa breve en la posición baja, luego activa los glúteos y los isquiotibiales para levantar la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/1009-kuMiR2T.jpg', 'videos/1009-kuMiR2T.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1023', 'band straight back stiff leg deadlift', 'upper legs', 'upper legs', 'band', 'Stand with your feet shoulder-width apart and place the band around your upper legs. Hold the band with both hands in front of your thighs, palms facing your body. Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground. Feel the stretch in your hamstrings as you lower the band. Engage your glutes and hamstrings to lift your body back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de las piernas. Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo. Manteniendo la espalda recta y las rodillas ligeramente flexionadas, flexiona las caderas y baja la banda hacia el suelo. Siente el estiramiento en los isquiotibiales mientras bajas la banda. Activa los glúteos y los isquiotibiales para levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/1023-lHeUULr.jpg', 'videos/1023-lHeUULr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1010', 'band straight leg deadlift', 'back', 'back', 'band', 'Stand with your feet shoulder-width apart and place the band around your feet. Hold the band with both hands, palms facing your body, and keep your arms straight. Engage your core and maintain a slight bend in your knees. Slowly hinge forward at your hips, keeping your back straight and chest lifted. Lower the band towards the ground while keeping your legs straight. Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los pies. Sujeta la banda con ambas manos, con las palmas mirando hacia el cuerpo, y mantén los brazos rectos. Activa el core y mantén una ligera flexión en las rodillas. Inclínate lentamente hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado. Baja la banda hacia el suelo manteniendo las piernas rectas. Haz una pausa breve en la posición baja y luego contrae los glúteos y los isquiotibiales para volver a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'spine', 'images/1010-KUaoUV8.jpg', 'videos/1010-KUaoUV8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1012', 'band twisting overhead press', 'shoulders', 'shoulders', 'band', 'Stand with your feet shoulder-width apart and place the band under your feet. Hold the band handles at shoulder height with your palms facing forward. Engage your core and press the band overhead, fully extending your arms. As you press, twist your torso to one side, keeping your hips stable. Pause for a moment at the top, then return to the starting position. Repeat the press and twist on the opposite side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies. Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante. Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos. Mientras empujas, gira el torso hacia un lado, manteniendo las caderas estables. Haz una pausa breve en la parte alta y luego vuelve a la posición inicial. Repite el empuje y el giro hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/1012-u4bAmKp.jpg', 'videos/1012-u4bAmKp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1369', 'band two legs calf raise - (band under both legs) v. 2', 'lower legs', 'lower legs', 'band', 'Stand with your feet shoulder-width apart and place a resistance band under both feet. Hold the ends of the band with your hands for stability. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca una banda elástica bajo ambos pies. Sujeta los extremos de la banda con las manos para mantener el equilibrio. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'ankles', '["ankles","feet"]'::jsonb, 'calves', 'images/1369-jl6uxZV.jpg', 'videos/1369-jl6uxZV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1013', 'band underhand pulldown', 'back', 'back', 'band', 'Attach the band to a high anchor point, such as a pull-up bar or sturdy beam. Stand facing the anchor point with your feet shoulder-width apart. Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart. Extend your arms fully overhead, keeping your elbows slightly bent. Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Extiende completamente los brazos por encima de la cabeza, manteniendo los codos ligeramente flexionados. Activa los dorsales y tira de la banda hacia abajo en dirección al pecho, juntando los omóplatos. Haz una pausa breve en la parte baja del movimiento, luego libera lentamente la tensión y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/1013-k6tUeqS.jpg', 'videos/1013-k6tUeqS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1014', 'band v-up', 'waist', 'waist', 'band', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band. Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda. Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/1014-H6ETwO9.jpg', 'videos/1014-H6ETwO9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1015', 'band vertical pallof press', 'waist', 'waist', 'band', 'Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height. Hold the band with both hands and step away from the anchor point, creating tension in the band. Position yourself perpendicular to the anchor point, with your side facing the band. Extend your arms straight out in front of you, keeping your hands at chest height. Engage your core and press the band away from your chest, fully extending your arms. Hold the position for a few seconds, then slowly bring the band back towards your chest. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho. Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda. Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda. Extiende los brazos rectos hacia delante, manteniendo las manos a la altura del pecho. Activa el core y empuja la banda alejándola del pecho, extendiendo completamente los brazos. Mantén la posición durante unos segundos y luego lleva lentamente la banda de vuelta hacia el pecho. Repite el número de repeticiones deseado, luego cambia de lado.', 'obliques', '["obliques","glutes"]'::jsonb, 'abs', 'images/1015-G7PXMlT.jpg', 'videos/1015-G7PXMlT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1016', 'band wrist curl', 'lower arms', 'lower arms', 'band', 'Sit on a bench or chair with your feet flat on the ground. Hold the band with both hands, palms facing up, and rest your forearms on your thighs. Slowly curl your wrists upward, squeezing your forearms. Pause for a moment at the top, then slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sujeta la banda con ambas manos, con las palmas hacia arriba, y apoya los antebrazos sobre los muslos. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos. Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps"]'::jsonb, 'forearms', 'images/1016-vUTfFHw.jpg', 'videos/1016-vUTfFHw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1017', 'band y-raise', 'shoulders', 'shoulders', 'band', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards. Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body. Squeeze your shoulder blades together at the top of the movement. Slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro. Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una ''Y'' con el cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/1017-aHDy5O5.jpg', 'videos/1017-aHDy5O5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0023', 'barbell alternate biceps curl', 'upper arms', 'upper arms', 'barbell', 'Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward. Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps. Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly begin to lower the barbells back to the starting position. Repeat for the desired number of repetitions, alternating arms.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra en cada mano, con las palmas mirando hacia delante. Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps. Continúa levantando las barras hasta que los bíceps estén completamente contraídos y las barras estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras comienzas a bajar lentamente las barras de vuelta a la posición inicial. Repite el número de repeticiones deseado, alternando los brazos.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0023-Yza7XrQ.jpg', 'videos/0023-Yza7XrQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0024', 'barbell bench front squat', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone. Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground. Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up. Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, justo debajo de la clavícula. Sujeta la barra con un agarre pronado, manteniendo los codos elevados y los brazos superiores paralelos al suelo. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado. Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes","calves"]'::jsonb, 'quads', 'images/0024-Y7YcmIJ.jpg', 'videos/0024-Y7YcmIJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0025', 'barbell bench press', 'chest', 'chest', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Lower the barbell slowly towards your chest, keeping your elbows tucked in. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0025-EIeI8Vf.jpg', 'videos/0025-EIeI8Vf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0026', 'barbell bench squat', 'upper legs', 'upper legs', 'barbell', 'Set up a barbell on a squat rack at chest height. Stand facing away from the rack, with your feet shoulder-width apart. Bend your knees and lower your body down into a squat position, keeping your back straight and chest up. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart. Lower your body down into a squat, keeping your knees in line with your toes. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Coloca una barra en un soporte de sentadillas a la altura del pecho. Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros. Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0026-W9pFVv1.jpg', 'videos/0026-W9pFVv1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1316', 'barbell bent arm pullover', 'back', 'back', 'barbell', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest. Lower the barbell behind your head while keeping your arms slightly bent. Pause for a moment, then raise the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho. Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'lats', 'images/1316-cA9FuWG.jpg', 'videos/1316-cA9FuWG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0027', 'barbell bent over row', 'back', 'back', 'barbell', 'Stand with your feet shoulder-width apart and knees slightly bent. Bend forward at the hips while keeping your back straight and chest up. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Tira de la barra hacia la parte inferior del pecho retrayendo los omóplatos y contrayendo los músculos de la espalda. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0027-eZyBC3j.jpg', 'videos/0027-eZyBC3j.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2407', 'barbell biceps curl (with arm blaster)', 'upper arms', 'upper arms', 'barbell', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Place your upper arms against the arm blaster, keeping your elbows close to your torso. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba. Coloca los brazos superiores contra el soporte para brazos, manteniendo los codos cerca del torso. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2407-aee2Fcj.jpg', 'videos/2407-aee2Fcj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0028', 'barbell clean and press', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and the barbell on the floor in front of you. Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body. As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest. As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up. From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti. Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo. Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho. Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba. Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes","shoulders","triceps"]'::jsonb, 'quads', 'images/0028-SGY8Zui.jpg', 'videos/0028-SGY8Zui.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0029', 'barbell clean-grip front squat', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward. Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair. Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante. Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla. Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/0029-qi996YS.jpg', 'videos/0029-qi996YS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0030', 'barbell close-grip bench press', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0030-J6Dx1Mu.jpg', 'videos/0030-J6Dx1Mu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0031', 'barbell curl', 'upper arms', 'upper arms', 'barbell', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward. Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly begin to lower the bar back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas mirando hacia delante. Mantén los codos cerca del torso y exhala mientras levantas el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras comienzas a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0031-25GPyDY.jpg', 'videos/0031-25GPyDY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0032', 'barbell deadlift', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and the barbell on the ground in front of you. Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees. As you stand up straight, squeeze your glutes and keep your core engaged. Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti. Flexiona las rodillas y las caderas para bajar el torso y agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas. Al ponerte de pie, aprieta los glúteos y mantén el core activado. Baja la barra de vuelta al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0032-ila4NZS.jpg', 'videos/0032-ila4NZS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0033', 'barbell decline bench press', 'chest', 'chest', 'barbell', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0033-GrO65fd.jpg', 'videos/0033-GrO65fd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0034', 'barbell decline bent arm pullover', 'back', 'back', 'barbell', 'Lie down on a decline bench with your head lower than your hips and your feet secured. Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest. Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent. Pause for a moment, then raise the barbell back to the starting position by contracting your lats. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos. Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho. Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial contrayendo los dorsales. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'lats', 'images/0034-hMEptv0.jpg', 'videos/0034-hMEptv0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0035', 'barbell decline close grip to skull press', 'upper arms', 'upper arms', 'barbell', 'Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip. Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary. Pause for a moment, then extend your arms to press the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta una barra con un agarre cerrado. Baja la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos. Haz una pausa breve y luego extiende los brazos para empujar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0035-LMGXZn8.jpg', 'videos/0035-LMGXZn8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1255', 'barbell decline pullover', 'chest', 'chest', 'barbell', 'Lie down on a decline bench with your head lower than your hips and your feet secured. Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart. Extend your arms above your chest, keeping a slight bend in your elbows. Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders. Pause for a moment, then return the barbell to the starting position by reversing the motion. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos. Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros. Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la barra describiendo un arco detrás de la cabeza, sintiendo un estiramiento en el pecho y los hombros. Haz una pausa breve y luego devuelve la barra a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1255-9sgNE2O.jpg', 'videos/1255-9sgNE2O.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0036', 'barbell decline wide-grip press', 'chest', 'chest', 'barbell', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows out to the sides. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Baja la barra hacia el pecho, manteniendo los codos hacia los lados. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0036-hl8DUh8.jpg', 'videos/0036-hl8DUh8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0037', 'barbell decline wide-grip pullover', 'back', 'back', 'barbell', 'Lie on a decline bench with your head lower than your hips and your feet secured. Hold a barbell with a wide grip and extend your arms straight above your chest. Lower the barbell behind your head in a controlled manner, keeping your arms straight. Pause for a moment, then raise the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos. Sujeta una barra con un agarre amplio y extiende los brazos rectos por encima del pecho. Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos rectos. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'lats', 'images/0037-Hj4FOCd.jpg', 'videos/0037-Hj4FOCd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0038', 'barbell drag curl', 'upper arms', 'upper arms', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Let the barbell hang at arm''s length in front of your thighs. Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba. Deja que la barra cuelgue a la longitud del brazo frente a los muslos. Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0038-IENzBdA.jpg', 'videos/0038-IENzBdA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1370', 'barbell floor calf raise', 'lower legs', 'lower legs', 'barbell', 'Place a barbell on the floor in front of you. Stand with the balls of your feet on the edge of the barbell, with your heels hanging off. Hold onto a stable object for balance if needed. Raise your heels as high as possible, using your calves to lift your body. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca una barra en el suelo frente a ti. Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Levanta los talones lo más alto posible, usando las pantorrillas para elevar el cuerpo. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1370-2IHEa2T.jpg', 'videos/1370-2IHEa2T.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0039', 'barbell front chest squat', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart, toes slightly turned out. Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra frente al pecho con las manos separadas a la altura de los hombros, los codos apuntando hacia delante. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/0039-IeTIEqg.jpg', 'videos/0039-IeTIEqg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0041', 'barbell front raise', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip. Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado. Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps"]'::jsonb, 'delts', 'images/0041-b2Uoz54.jpg', 'videos/0041-b2Uoz54.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0040', 'barbell front raise and pullover', 'chest', 'chest', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Keep your arms straight and raise the barbell in front of you until it reaches shoulder height. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Next, lower the barbell behind your head, keeping your arms straight. Pause for a moment at the bottom, then raise the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Mantén los brazos rectos y levanta la barra frente a ti hasta que alcance la altura de los hombros. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. A continuación, baja la barra detrás de la cabeza, manteniendo los brazos rectos. Haz una pausa breve en la parte baja y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0040-33AzZeV.jpg', 'videos/0040-33AzZeV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0042', 'barbell front squat', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart, toes slightly turned out. Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra frente a los hombros, apoyándola sobre la clavícula y los hombros. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/0042-zG0zs85.jpg', 'videos/0042-zG0zs85.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0043', 'barbell full squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down. Bend at the knees and hips, pushing your hips back and down as if sitting into a chair. Lower yourself until your thighs are parallel to the ground or slightly below. Keep your knees in line with your toes and your weight in your heels. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo. Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/0043-qXTaZnJ.jpg', 'videos/0043-qXTaZnJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1461', 'barbell full squat (back pov)', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down. Bend at the knees and hips, pushing your hips back and down as if sitting into a chair. Lower your body until your thighs are parallel to the ground or slightly below. Keep your knees in line with your toes and your weight in your heels. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo. Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/1461-DhMl549.jpg', 'videos/1461-DhMl549.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1462', 'barbell full squat (side pov)', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down. Bend at the knees and hips, pushing your hips back and down as if sitting into a chair. Lower your body until your thighs are parallel to the ground or slightly below. Keep your knees in line with your toes and your weight in your heels. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo. Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/1462-iYzB0Cz.jpg', 'videos/1462-iYzB0Cz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1545', 'barbell full zercher squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position. Keep your knees in line with your toes and your weight in your heels. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, squeezing your glutes at the top of the movement. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra en el pliegue de los codos, agarrándola con las manos para mantener la estabilidad. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, apretando los glúteos en la parte alta del movimiento. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/1545-vR1vold.jpg', 'videos/1545-vR1vold.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1409', 'barbell glute bridge', 'upper legs', 'upper legs', 'barbell', 'Start by lying flat on your back on the ground with your knees bent and feet flat on the floor. Place a barbell across your hips, holding it securely with both hands. Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, squeezing your glutes. Slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos. Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa breve en la parte alta, apretando los glúteos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/1409-qKBpF7I.jpg', 'videos/1409-qKBpF7I.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3562', 'barbell glute bridge two legs on bench (male)', 'upper legs', 'upper legs', 'barbell', 'Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart. Place a barbell across your hips, holding it securely with both hands. Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders. Pause for a moment at the top, squeezing your glutes. Slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas. Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos. Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros. Haz una pausa breve en la parte alta, apretando los glúteos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","core"]'::jsonb, 'glutes', 'images/3562-qg2PGl6.jpg', 'videos/3562-qg2PGl6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0044', 'barbell good morning', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper back. Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward. Repeat for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda. Manteniendo la espalda recta y el core activado, flexiona las caderas hacia delante, empujando los glúteos hacia atrás como si intentaras tocar la pared detrás de ti con ellos. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Haz una pausa breve y luego vuelve a la posición inicial apretando los glúteos y empujando las caderas hacia delante. Repite el número de repeticiones deseado.', 'lower back', '["lower back"]'::jsonb, 'hamstrings', 'images/0044-XlZ4lAC.jpg', 'videos/0044-XlZ4lAC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0045', 'barbell guillotine bench press', 'chest', 'chest', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell slowly towards your neck, keeping your elbows pointed outwards. Pause for a moment when the barbell is just above your neck. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera. Haz una pausa breve cuando la barra esté justo encima del cuello. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0045-GXoaSgn.jpg', 'videos/0045-GXoaSgn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0046', 'barbell hack squat', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart and your toes slightly turned out. Hold the barbell behind your legs, resting it on your upper thighs. Lower your body by bending at the knees and hips, keeping your back straight and your chest up. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos. Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0046-5VCj6iH.jpg', 'videos/0046-5VCj6iH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1436', 'barbell high bar squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart, toes slightly turned out. Place the barbell on your upper back, resting it on your traps. Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees. Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras comienzas a bajar en sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/1436-Gnfo4FM.jpg', 'videos/1436-Gnfo4FM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0047', 'barbell incline bench press', 'chest', 'chest', 'barbell', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos a un ángulo de 45 grados. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0047-3TZduzM.jpg', 'videos/0047-3TZduzM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1719', 'barbell incline close grip bench press', 'upper arms', 'upper arms', 'barbell', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1719-gx7s7uF.jpg', 'videos/1719-gx7s7uF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0048', 'barbell incline reverse-grip press', 'upper arms', 'upper arms', 'barbell', 'Set up an incline bench at a 45-degree angle. Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart. Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Recuéstate en el banco y agarra la barra con un agarre invertido, con las manos un poco más separadas que el ancho de los hombros. Saca la barra del soporte y bájala hacia la parte superior del pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0048-641mIfk.jpg', 'videos/0048-641mIfk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0049', 'barbell incline row', 'back', 'back', 'barbell', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest against the pad and your feet flat on the ground. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and your core engaged. Pull the barbell towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho apoyado en el respaldo y los pies planos sobre el suelo. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Mantén la espalda recta y el core activado. Tira de la barra hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0049-dmgMp3n.jpg', 'videos/0049-dmgMp3n.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0050', 'barbell incline shoulder raise', 'chest', 'chest', 'barbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the pad and feet flat on the ground. Hold a barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell up to shoulder height, keeping your elbows slightly bent. Slowly raise the barbell overhead, extending your arms fully. Pause for a moment at the top, then slowly lower the barbell back to shoulder height. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados. Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","trapezius"]'::jsonb, 'serratus anterior', 'images/0050-xi0yckC.jpg', 'videos/0050-xi0yckC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0051', 'barbell jefferson squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist. Step your left foot forward and your right foot back, keeping your feet shoulder-width apart. Bend your knees and lower your body down into a squat position, keeping your back straight and chest up. Push through your heels to stand back up to the starting position. Repeat the movement, alternating your forward and back foot with each repetition.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre pronado, apoyándola en la parte delantera del cuerpo, justo debajo de la cintura. Da un paso con el pie izquierdo hacia delante y el pie derecho hacia atrás, manteniendo los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Empuja con los talones para volver a ponerte de pie en la posición inicial. Repite el movimiento, alternando el pie delantero y el trasero en cada repetición.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0051-pkSoCW9.jpg', 'videos/0051-pkSoCW9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0052', 'barbell jm bench press', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows tucked in close to your body. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0052-ZsiqXYa.jpg', 'videos/0052-ZsiqXYa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0053', 'barbell jump squat', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Lower your body into a squat position by bending your knees and pushing your hips back. Once you reach the bottom of the squat, explode upwards by jumping off the ground. As you jump, extend your hips, knees, and ankles, pushing through your toes. Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo. Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies. Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0053-1gFNTZV.jpg', 'videos/0053-1gFNTZV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1410', 'barbell lateral lunge', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back. Take a big step to the side with your right foot, keeping your left foot planted. Bend your right knee and lower your body down into a lunge position, keeping your left leg straight. Push off with your right foot and return to the starting position. Repeat on the other side, stepping with your left foot.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo. Flexiona la rodilla derecha y baja el cuerpo hacia una posición de zancada, manteniendo la pierna izquierda recta. Empuja con el pie derecho y vuelve a la posición inicial. Repite hacia el otro lado, dando el paso con el pie izquierdo.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1410-py1HSzx.jpg', 'videos/1410-py1HSzx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1435', 'barbell low bar squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and the barbell resting on your upper back. Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda. Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1435-bTpEUcm.jpg', 'videos/1435-bTpEUcm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0054', 'barbell lunge', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back. Take a step forward with your right foot, keeping your torso upright. Lower your body by bending your right knee until your thigh is parallel to the ground. Push through your right heel to return to the starting position. Repeat with your left leg, alternating legs for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda. Da un paso hacia delante con el pie derecho, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0054-t8iSghb.jpg', 'videos/0054-t8iSghb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1720', 'barbell lying back of the head tricep extension', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1720-yg8Totb.jpg', 'videos/1720-yg8Totb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0055', 'barbell lying close-grip press', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Slowly lower the barbell towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell touches your chest, then push it back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas mirando hacia los pies. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0055-EcaV7aL.jpg', 'videos/0055-EcaV7aL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0056', 'barbell lying close-grip triceps extension', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up. Extend your arms fully, lifting the barbell above your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Pause for a moment at the bottom, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas hacia arriba. Extiende completamente los brazos, levantando la barra por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0056-HJ63mSO.jpg', 'videos/0056-HJ63mSO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0057', 'barbell lying extension', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0057-EMpUwRI.jpg', 'videos/0057-EMpUwRI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0058', 'barbell lying lifting (on hip)', 'upper legs', 'upper legs', 'barbell', 'Lie flat on your back on a bench with your feet flat on the ground and your knees bent. Hold the barbell with an overhand grip and position it on your hips. Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta la barra con un agarre pronado y colócala sobre las caderas. Activando los glúteos, levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/0058-SNFfUff.jpg', 'videos/0058-SNFfUff.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0059', 'barbell lying preacher curl', 'upper arms', 'upper arms', 'barbell', 'Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco predicador con el pecho apoyado en el respaldo y los brazos extendidos sobre el borde, sujetando una barra con un agarre supino. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0059-SYJ4Bkt.jpg', 'videos/0059-SYJ4Bkt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0061', 'barbell lying triceps extension', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Pause for a moment at the bottom, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0061-iZop9xO.jpg', 'videos/0061-iZop9xO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0060', 'barbell lying triceps extension skull crusher', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve cuando la barra esté justo encima de la frente y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0060-h8LFzo9.jpg', 'videos/0060-h8LFzo9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0063', 'barbell narrow stance squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and toes pointing slightly outward. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0063-elhhVgj.jpg', 'videos/0063-elhhVgj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0064', 'barbell one arm bent over row', 'back', 'back', 'barbell', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip. Bend forward at the hips, keeping your back straight and your head in a neutral position. Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Lower the barbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral. Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Baja la barra de vuelta a la posición inicial de forma controlada. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0064-Jsgsc27.jpg', 'videos/0064-Jsgsc27.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0065', 'barbell one arm floor press', 'upper arms', 'upper arms', 'barbell', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest. Slowly lower the barbell towards your chest, keeping your elbow close to your body. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho. Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0065-vtusOWT.jpg', 'videos/0065-vtusOWT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0066', 'barbell one arm side deadlift', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip. Keep your back straight and your core engaged. Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up. Lower the barbell as far as you can while maintaining good form. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado. Mantén la espalda recta y el core activado. Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado. Baja la barra tanto como puedas manteniendo una buena forma. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'hamstrings', '["hamstrings","quadriceps","lower back"]'::jsonb, 'glutes', 'images/0066-2DxtqHL.jpg', 'videos/0066-2DxtqHL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0067', 'barbell one arm snatch', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart, toes pointing slightly outwards. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend your knees and lower your hips into a squat position, keeping your back straight and chest up. Explosively extend your hips, knees, and ankles, driving the barbell upwards. As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body. Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow. Lower the barbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba. Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo. Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo. Baja la barra de vuelta a la posición inicial de forma controlada. Repite el número de repeticiones deseado, luego cambia de brazo.', 'traps', '["traps","forearms","core"]'::jsonb, 'delts', 'images/0067-xHKN2s8.jpg', 'videos/0067-xHKN2s8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0068', 'barbell one leg squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Lift one foot off the ground and extend it forward, keeping it parallel to the ground. Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight. Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo. Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta. Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0068-uKyN64F.jpg', 'videos/0068-uKyN64F.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0069', 'barbell overhead squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell with a wide grip, positioning it overhead with your arms fully extended. Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos. Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves","core"]'::jsonb, 'quads', 'images/0069-gfk9kD4.jpg', 'videos/0069-gfk9kD4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1411', 'barbell palms down wrist curl over a bench', 'lower arms', 'lower arms', 'barbell', 'Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down. Hold a barbell with an overhand grip, hands shoulder-width apart. Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary. Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros. Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos. Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/1411-yzYH9pI.jpg', 'videos/1411-yzYH9pI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1412', 'barbell palms up wrist curl over a bench', 'lower arms', 'lower arms', 'barbell', 'Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up. Rest your forearms on the bench, allowing your wrists to hang off the edge. Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'forearms', 'images/1412-SJAA2IQ.jpg', 'videos/1412-SJAA2IQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3017', 'barbell pendlay row', 'back', 'back', 'barbell', 'Stand with your feet shoulder-width apart and your knees slightly bent. Bend forward at the hips, keeping your back straight and your chest up. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Pull the barbell towards your upper abdomen, squeezing your shoulder blades together. Lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/3017-r0z6xzQ.jpg', 'videos/3017-r0z6xzQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1751', 'barbell pin presses', 'upper arms', 'upper arms', 'barbell', 'Set up a barbell on a power rack at chest height. Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart. Grip the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended. Lower the barbell down towards your chest, keeping your elbows tucked in close to your body. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca una barra en un rack de potencia a la altura del pecho. Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1751-bndCa3Q.jpg', 'videos/1751-bndCa3Q.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0070', 'barbell preacher curl', 'upper arms', 'upper arms', 'barbell', 'Sit on a preacher bench with your upper arms resting on the pad and your chest against the support. Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte. Agarra la barra con un agarre supino, un poco más ancho que la separación de los hombros. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0070-qOgPVf6.jpg', 'videos/0070-qOgPVf6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0071', 'barbell press sit-up', 'waist', 'waist', 'barbell', 'Lie flat on your back on a mat with your knees bent and feet flat on the ground. Hold the barbell with an overhand grip, resting it on your chest. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, apoyándola sobre el pecho. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest"]'::jsonb, 'abs', 'images/0071-wnEscH8.jpg', 'videos/0071-wnEscH8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0072', 'barbell prone incline curl', 'upper arms', 'upper arms', 'barbell', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting against it. Hold a barbell with an underhand grip, shoulder-width apart. Extend your arms fully, allowing the barbell to hang down towards the floor. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sujeta una barra con un agarre supino, separado a la altura de los hombros. Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0072-WLvTAv5.jpg', 'videos/0072-WLvTAv5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0073', 'barbell pullover', 'back', 'back', 'barbell', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest. Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats. Pause for a moment, then raise the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","triceps"]'::jsonb, 'lats', 'images/0073-i6LWjok.jpg', 'videos/0073-i6LWjok.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0022', 'barbell pullover to press', 'back', 'back', 'barbell', 'Lie flat on a bench with your head at one end and your feet on the ground. Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest. Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats. Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales. Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest","shoulders"]'::jsonb, 'lats', 'images/0022-znLogoF.jpg', 'videos/0022-znLogoF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0074', 'barbell rack pull', 'upper legs', 'upper legs', 'barbell', 'Set up a barbell on a rack at knee height. Stand with your feet shoulder-width apart, toes pointing slightly outwards. Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart. Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top. Lower the barbell back down to the starting position by bending at the hips and knees. Repeat for the desired number of repetitions.', 'Coloca una barra en un soporte a la altura de la rodilla. Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros. Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta. Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0074-za9Ni4z.jpg', 'videos/0074-za9Ni4z.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0075', 'barbell rear delt raise', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/0075-Ln9iTbU.jpg', 'videos/0075-Ln9iTbU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0076', 'barbell rear delt row', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up. Pull the barbell towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado. Tira de la barra hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids","biceps"]'::jsonb, 'delts', 'images/0076-S9zHIvU.jpg', 'videos/0076-S9zHIvU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0078', 'barbell rear lunge', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back. Take a step backward with your right foot, landing on the ball of your foot. Bend both knees to lower your body until your left thigh is parallel to the ground. Push through your left heel to return to the starting position. Repeat with the other leg.', 'Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Empuja con el talón izquierdo para volver a la posición inicial. Repite con la otra pierna.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0078-VaP75jl.jpg', 'videos/0078-VaP75jl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0077', 'barbell rear lunge v. 2', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Take a step backward with your right foot, landing on the ball of your foot. Bend both knees to lower your body until your left thigh is parallel to the ground. Push through your left heel to return to the starting position. Repeat with the other leg.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Empuja con el talón izquierdo para volver a la posición inicial. Repite con la otra pierna.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0077-62Nw60O.jpg', 'videos/0077-62Nw60O.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0079', 'barbell revers wrist curl v. 2', 'lower arms', 'lower arms', 'barbell', 'Sit on a bench with your feet flat on the ground and your knees bent. Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos separadas a la altura de los hombros. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0079-qDnGfDb.jpg', 'videos/0079-qDnGfDb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2187', 'barbell reverse close-grip bench press', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a reverse grip, hands shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Slowly lower the barbell down towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell is just above your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra esté justo encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/2187-YqJw82s.jpg', 'videos/2187-YqJw82s.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0080', 'barbell reverse curl', 'upper arms', 'upper arms', 'barbell', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0080-xNrS20v.jpg', 'videos/0080-xNrS20v.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0118', 'barbell reverse grip bent over row', 'back', 'back', 'barbell', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor. Pull the barbell towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo. Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0118-SzX3uzM.jpg', 'videos/0118-SzX3uzM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1256', 'barbell reverse grip decline bench press', 'chest', 'chest', 'barbell', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1256-DotAgEF.jpg', 'videos/1256-DotAgEF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1257', 'barbell reverse grip incline bench press', 'chest', 'chest', 'barbell', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1257-DU7I633.jpg', 'videos/1257-DU7I633.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1317', 'barbell reverse grip incline bench row', 'back', 'back', 'barbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench facing the backrest with your chest against it. Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart. Keep your back straight and core engaged. Pull the barbell towards your upper abdomen, squeezing your shoulder blades together. Pause for a moment at the top of the movement. Slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco frente al respaldo con el pecho apoyado contra él. Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado. Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento. Baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1317-8d8qJQI.jpg', 'videos/1317-8d8qJQI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1721', 'barbell reverse grip skullcrusher', 'upper arms', 'upper arms', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart. Extend your arms straight up over your chest, keeping your elbows in and your wrists straight. Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary. Pause for a moment at the bottom, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros. Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas. Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/1721-yRLPCLu.jpg', 'videos/1721-yRLPCLu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0081', 'barbell reverse preacher curl', 'upper arms', 'upper arms', 'barbell', 'Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip. Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0081-4LIG9xr.jpg', 'videos/0081-4LIG9xr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0082', 'barbell reverse wrist curl', 'lower arms', 'lower arms', 'barbell', 'Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the barbell towards your body. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0082-LsZkfU6.jpg', 'videos/0082-LsZkfU6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0084', 'barbell rollerout', 'waist', 'waist', 'barbell', 'Kneel on the floor and hold a barbell with both hands, shoulder-width apart. Roll the barbell forward, extending your arms and keeping your core engaged. Continue rolling forward until your body is fully extended and your arms are overhead. Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control. Repeat for the desired number of repetitions.', 'Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros. Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado. Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza. Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control. Repite el número de repeticiones deseado.', 'lower back', '["lower back"]'::jsonb, 'abs', 'images/0084-7M66AVi.jpg', 'videos/0084-7M66AVi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0083', 'barbell rollerout from bench', 'waist', 'waist', 'barbell', 'Start by kneeling on the floor with a barbell placed on a bench in front of you. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you. Continue rolling the barbell forward until your body is fully extended and your arms are overhead. Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position. Repeat for the desired number of repetitions.', 'Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti. Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza. Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'abs', 'images/0083-Gxg9lDc.jpg', 'videos/0083-Gxg9lDc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0085', 'barbell romanian deadlift', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and your toes pointing forward. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend at the hips, keeping your back straight and your knees slightly bent. Lower the barbell towards the ground, keeping it close to your body. Feel the stretch in your hamstrings as you lower the barbell. Once you feel a stretch in your hamstrings, push your hips forward and stand up straight. Squeeze your glutes at the top of the movement. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Baja la barra hacia el suelo, manteniéndola cerca del cuerpo. Siente el estiramiento en los isquiotibiales mientras bajas la barra. Cuando sientas el estiramiento en los isquiotibiales, empuja las caderas hacia delante y ponte de pie. Aprieta los glúteos en la parte alta del movimiento. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0085-wQ2c4XD.jpg', 'videos/0085-wQ2c4XD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0086', 'barbell seated behind head military press', 'shoulders', 'shoulders', 'barbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and bring it down to shoulder level, behind your head. Press the barbell upward until your arms are fully extended. Lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza. Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0086-ngPpyRS.jpg', 'videos/0086-ngPpyRS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0087', 'barbell seated bradford rocky press', 'shoulders', 'shoulders', 'barbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward. Press the barbell overhead, fully extending your arms. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0087-0dCyly0.jpg', 'videos/0087-0dCyly0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0088', 'barbell seated calf raise', 'lower legs', 'lower legs', 'barbell', 'Sit on a bench with your feet flat on the floor and a barbell resting on your thighs. Place the balls of your feet on a raised platform, such as a block or step. Position the barbell across your thighs and hold it securely with your hands. Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos. Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón. Coloca la barra sobre los muslos y sujétala con firmeza con las manos. Manteniendo la espalda recta y el core activado, levanta los talones del suelo extendiendo los tobillos. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'calves', 'images/0088-ktsFQAZ.jpg', 'videos/0088-ktsFQAZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1371', 'barbell seated calf raise', 'lower legs', 'lower legs', 'barbell', 'Sit on a bench with your feet flat on the floor and a barbell resting on your thighs. Place the balls of your feet on a raised platform, such as a block or step. Lower your heels as far as possible, feeling a stretch in your calves. Raise your heels as high as possible, contracting your calves. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos. Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón. Baja los talones tanto como sea posible, sintiendo un estiramiento en las pantorrillas. Levanta los talones lo más alto posible, contrayendo las pantorrillas. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1371-ipvgBnC.jpg', 'videos/1371-ipvgBnC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1718', 'barbell seated close grip behind neck triceps extension', 'upper arms', 'upper arms', 'barbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with a close grip behind your neck, palms facing forward. Keep your elbows close to your head and slowly lower the barbell towards the back of your head. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante. Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1718-4CBIBOM.jpg', 'videos/1718-4CBIBOM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0089', 'barbell seated close-grip concentration curl', 'upper arms', 'upper arms', 'barbell', 'Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart. Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros. Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0089-1V1gj1u.jpg', 'videos/0089-1V1gj1u.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0090', 'barbell seated good morning', 'upper legs', 'upper legs', 'barbell', 'Sit on a bench with your feet flat on the ground and a barbell resting on your upper back. Keep your back straight and your chest up. Slowly hinge forward at the hips, lowering your torso towards the ground. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda. Mantén la espalda recta y el pecho elevado. Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0090-d960PgE.jpg', 'videos/0090-d960PgE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0091', 'barbell seated overhead press', 'shoulders', 'shoulders', 'barbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward. Press the barbell overhead by extending your arms fully. Pause for a moment at the top, then slowly lower the barbell back to shoulder level. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia delante. Empuja la barra por encima de la cabeza extendiendo completamente los brazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0091-kTbSH9h.jpg', 'videos/0091-kTbSH9h.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0092', 'barbell seated overhead triceps extension', 'upper arms', 'upper arms', 'barbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead. Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head. Pause for a moment, then extend your arms to raise the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza. Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza. Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0092-5uFK1xr.jpg', 'videos/0092-5uFK1xr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0094', 'barbell seated twist', 'waist', 'waist', 'barbell', 'Sit on a flat bench with your feet flat on the ground and your knees bent. Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent. Engage your core and slowly twist your torso to one side, keeping your back straight. Pause for a moment at the end of the twist, then slowly rotate back to the starting position. Repeat the twist to the other side. Continue alternating sides for the desired number of repetitions.', 'Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados. Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta. Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial. Repite el giro hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0094-dFSNDOA.jpg', 'videos/0094-dFSNDOA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0095', 'barbell shrug', 'back', 'back', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip. Keep your arms straight and your back straight throughout the exercise. Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top. Hold for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado. Mantén los brazos rectos y la espalda recta durante todo el ejercicio. Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta. Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'traps', 'images/0095-dG7tG5y.jpg', 'videos/0095-dG7tG5y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0096', 'barbell side bent v. 2', 'waist', 'waist', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down. Keep your back straight and core engaged throughout the exercise. Slowly bend your torso to the right side, lowering the barbell towards your right knee. Pause for a moment, then return to the starting position. Repeat the movement on the left side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo. Mantén la espalda recta y el core activado durante todo el ejercicio. Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0096-i4JkUaL.jpg', 'videos/0096-i4JkUaL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0098', 'barbell side split squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold a barbell across your upper back, resting it on your traps. Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips. As you lower, push your knees out to the sides and keep your weight on your heels. Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas. Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones. Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0098-W31mMjd.jpg', 'videos/0098-W31mMjd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0097', 'barbell side split squat v. 2', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards. Hold a barbell across your upper back, resting it on your shoulders. Take a big step to the side with your right foot, keeping your left foot planted. Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight. Push through your right heel to return to the starting position. Repeat on the other side, stepping out with your left foot. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros. Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo. Flexiona la rodilla derecha y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y la espalda recta. Empuja con el talón derecho para regresar a la posición inicial. Repite hacia el otro lado, dando el paso con el pie izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0097-HUEqZ1y.jpg', 'videos/0097-HUEqZ1y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1756', 'barbell single leg deadlift', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip. Shift your weight onto your left foot and lift your right foot slightly off the ground. Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance. Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono. Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio. Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada. Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/1756-gEyURal.jpg', 'videos/1756-gEyURal.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0099', 'barbell single leg split squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back. Take a large step forward with one leg, keeping your torso upright. Lower your body by bending your front knee and hip, while keeping your back leg straight. Continue lowering until your front thigh is parallel to the ground. Pause for a moment, then push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta. Continúa bajando hasta que el muslo delantero quede paralelo al suelo. Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0099-gGNQmVt.jpg', 'videos/0099-gGNQmVt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2799', 'barbell sitted alternate leg raise', 'waist', 'waist', 'barbell', 'Sit on a bench with your back straight and hold a barbell across your thighs. Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground. Lower the raised leg back down and repeat with the other leg. Continue alternating legs for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos. Manteniendo las piernas rectas, levanta una pierna lo más alto posible mientras mantienes la otra pierna en el suelo. Baja la pierna elevada y repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/2799-G7xoEzr.jpg', 'videos/2799-G7xoEzr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2800', 'barbell sitted alternate leg raise (female)', 'waist', 'waist', 'barbell', 'Sit on a bench with your back straight and hold a barbell across your thighs. Place your hands on the sides of the bench for support. Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground. Lower the leg back down and repeat with the other leg. Continue alternating legs for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos. Coloca las manos a los lados del banco para apoyarte. Manteniendo las piernas rectas, levanta una pierna lo más alto posible manteniéndola paralela al suelo. Baja la pierna y repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors","quadriceps"]'::jsonb, 'abs', 'images/2800-BCs0G2F.jpg', 'videos/2800-BCs0G2F.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0100', 'barbell skier', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground. As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo. Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0100-4Leypho.jpg', 'videos/0100-4Leypho.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0101', 'barbell speed squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, squeezing your glutes at the top. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras llevas las caderas hacia atrás y hacia abajo, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0101-euI1BwR.jpg', 'videos/0101-euI1BwR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2810', 'barbell split squat v. 2', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Take a large step forward with your right foot, keeping your torso upright. Lower your body by bending your knees and hips until your right thigh is parallel to the ground. Pause for a moment, then push through your right heel to return to the starting position. Repeat with your left leg forward for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia adelante con el pie derecho, manteniendo el torso erguido. Baja el cuerpo flexionando las rodillas y las caderas hasta que el muslo derecho quede paralelo al suelo. Haz una pausa breve, luego empuja con el talón derecho para volver a la posición inicial. Repite con la pierna izquierda adelante el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/2810-HBYyX94.jpg', 'videos/2810-HBYyX94.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0102', 'barbell squat (on knees)', 'upper legs', 'upper legs', 'barbell', 'Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward. Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart. Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Comienza arrodillado en el suelo con las rodillas separadas a la altura de las caderas y las puntas de los pies apuntando hacia adelante. Coloca una barra sobre los hombros, sujetándola con agarre prono y las manos un poco más separadas que el ancho de los hombros. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas, manteniendo la espalda recta. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0102-oR7O9LW.jpg', 'videos/0102-oR7O9LW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2798', 'barbell squat jump step rear lunge', 'upper legs', 'upper legs', 'barbell', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Lower your body into a squat position by bending your knees and pushing your hips back. Explode upwards, jumping off the ground as high as you can. Land softly on your feet and immediately step back with one leg into a reverse lunge. Lower your body down until your front thigh is parallel to the ground, keeping your back straight. Push through your front heel to return to the starting position. Repeat the jump and lunge sequence on the other leg. Continue alternating legs for the desired number of repetitions.', 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Impúlsate explosivamente hacia arriba, saltando del suelo lo más alto que puedas. Aterriza suavemente sobre los pies y de inmediato retrocede con una pierna hacia una zancada inversa. Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta. Empuja con el talón delantero para volver a la posición inicial. Repite la secuencia de salto y zancada con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/2798-RYcV1kH.jpg', 'videos/2798-RYcV1kH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0103', 'barbell standing ab rollerout', 'waist', 'waist', 'barbell', 'Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs. Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended. Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head. Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente a los muslos. Activa el core y enrolla lentamente la barra hacia el suelo, manteniendo la espalda recta y los brazos extendidos. Continúa enrollando la barra hacia adelante hasta que el cuerpo esté completamente extendido y las manos queden justo sobre la cabeza. Haz una pausa breve, luego enrolla lentamente la barra de vuelta hacia los muslos, manteniendo el control y el core activado. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","lower back"]'::jsonb, 'abs', 'images/0103-xnInPfE.jpg', 'videos/0103-xnInPfE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0104', 'barbell standing back wrist curl', 'lower arms', 'lower arms', 'barbell', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip. Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body. Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono. Apoya la barra sobre el dorso de las manos con las palmas hacia abajo y los dedos apuntando hacia el cuerpo. Manteniendo los brazos superiores quietos, exhala y flexiona las muñecas hacia arriba lo más posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'forearms', 'images/0104-2qTvJAZ.jpg', 'videos/0104-2qTvJAZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0105', 'barbell standing bradford press', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip. Press the barbell overhead, fully extending your arms. Lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra frente a los hombros con agarre prono. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0105-dCPESfR.jpg', 'videos/0105-dCPESfR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1372', 'barbell standing calf raise', 'lower legs', 'lower legs', 'barbell', 'Stand with your feet shoulder-width apart and place a barbell across your upper back. Raise your heels off the ground as high as possible, using only your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, apoyándote solo en las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1372-8ozhUIZ.jpg', 'videos/1372-8ozhUIZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0106', 'barbell standing close grip curl', 'upper arms', 'upper arms', 'barbell', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly begin to bring the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos juntas. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Exhala al flexionar el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras comienzas a llevar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0106-4dUn2iv.jpg', 'videos/0106-4dUn2iv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1456', 'barbell standing close grip military press', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart. Lift the barbell to shoulder height, keeping your elbows close to your body. Press the barbell overhead, extending your arms fully. Lower the barbell back to shoulder height. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, manos un poco más juntas que el ancho de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos cerca del cuerpo. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de nuevo a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/1456-wdRZISl.jpg', 'videos/1456-wdRZISl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2414', 'barbell standing concentration curl', 'upper arms', 'upper arms', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up. Rest your opposite hand on your thigh for support. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the weight back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba. Apoya la otra mano sobre el muslo para mayor estabilidad. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2414-vsMcDi9.jpg', 'videos/2414-vsMcDi9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0107', 'barbell standing front raise over head', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip. Keep your back straight and engage your core. Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down. Continue lifting until the barbell is slightly above shoulder level. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra frente a los muslos con agarre prono. Mantén la espalda recta y activa el core. Levanta lentamente la barra frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que la barra quede ligeramente por encima del nivel de los hombros. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0107-S8mo30S.jpg', 'videos/0107-S8mo30S.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0108', 'barbell standing leg calf raise', 'lower legs', 'lower legs', 'barbell', 'Stand with your feet shoulder-width apart and place a barbell across your upper back. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/0108-rGwhJ5o.jpg', 'videos/0108-rGwhJ5o.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0109', 'barbell standing overhead triceps extension', 'upper arms', 'upper arms', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip. Raise the barbell overhead, fully extending your arms. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then raise the barbell back to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0109-dZl9Q27.jpg', 'videos/0109-dZl9Q27.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0110', 'barbell standing reverse grip curl', 'upper arms', 'upper arms', 'barbell', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona el peso contrayendo los bíceps, llevando la barra lo más cerca posible de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0110-LWuA3aZ.jpg', 'videos/0110-LWuA3aZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0111', 'barbell standing rocking leg calf raise', 'lower legs', 'lower legs', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Raise your heels off the ground as high as possible, balancing on the balls of your feet. Slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, manteniendo el equilibrio sobre las puntas de los pies. Baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'calves', 'images/0111-6HiHHe0.jpg', 'videos/0111-6HiHHe0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0112', 'barbell standing twist', 'waist', 'waist', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down. Engage your core and keep your back straight throughout the exercise. Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable. Pause for a moment at the end of the twist, then slowly return to the starting position. Repeat the twist to the left side. Continue alternating twists for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo. Activa el core y mantén la espalda recta durante todo el ejercicio. Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado izquierdo. Continúa alternando los giros el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0112-yQe5HpE.jpg', 'videos/0112-yQe5HpE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1629', 'barbell standing wide grip biceps curl', 'upper arms', 'upper arms', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart. Keep your back straight and your elbows close to your torso. Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos más separadas que el ancho de los hombros. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona la barra hacia los hombros, manteniendo los brazos superiores quietos. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1629-faHKVkK.jpg', 'videos/1629-faHKVkK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1457', 'barbell standing wide military press', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width. Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar. Press the barbell overhead, extending your arms fully. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/1457-Kyd9Rz5.jpg', 'videos/1457-Kyd9Rz5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0113', 'barbell standing wide-grip curl', 'upper arms', 'upper arms', 'barbell', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart. Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body. Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros. Deja que la barra cuelgue a la longitud del brazo frente a los muslos, con las palmas mirando hacia afuera del cuerpo. Manteniendo los brazos superiores quietos, exhala y flexiona la barra hacia arriba contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/0113-NdIb5Z1.jpg', 'videos/0113-NdIb5Z1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0114', 'barbell step-up', 'upper legs', 'upper legs', 'barbell', 'Stand in front of a bench or step with a barbell resting on your upper back. Place one foot on the bench or step, ensuring your entire foot is in contact with the surface. Push through your heel and step up onto the bench or step, fully extending your hip and knee. Pause briefly at the top, then lower yourself back down to the starting position. Repeat with the opposite leg. Continue alternating legs for the desired number of repetitions.', 'Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda. Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla. Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial. Repite con la pierna contraria. Continúa alternando las piernas durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0114-Kxquu2E.jpg', 'videos/0114-Kxquu2E.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0115', 'barbell stiff leg good morning', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the barbell across your upper back, resting it on your traps. Keeping your back straight, hinge forward at the hips, pushing your glutes back. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Engage your glutes and hamstrings to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Manteniendo la espalda recta, inclínate hacia adelante desde las caderas, empujando los glúteos hacia atrás. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Activa los glúteos y los isquiotibiales para volver a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0115-JrOHAZc.jpg', 'videos/0115-JrOHAZc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0116', 'barbell straight leg deadlift', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and your toes pointing forward. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent. Lower the barbell until you feel a stretch in your hamstrings. Engage your hamstrings and glutes to lift the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las caderas y baja la barra hacia el suelo, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Baja la barra hasta que sientas un estiramiento en los isquiotibiales. Activa los isquiotibiales y los glúteos para levantar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","lower back"]'::jsonb, 'hamstrings', 'images/0116-hrVQWvE.jpg', 'videos/0116-hrVQWvE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0117', 'barbell sumo deadlift', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards. Place a barbell on the ground in front of you, centered between your feet. Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip. Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously. As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes. Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Coloca una barra en el suelo frente a ti, centrada entre los pies. Flexiona las rodillas y baja las caderas, manteniendo la espalda recta y el pecho elevado, para sujetar la barra con agarre prono. Activa el core y empuja con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas simultáneamente. Al levantar, mantén el pecho elevado y la espalda recta, y empuja las caderas hacia adelante para activar completamente los glúteos. Haz una pausa breve en la parte más alta, luego baja lentamente la barra de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","lower back"]'::jsonb, 'glutes', 'images/0117-KgI0tqW.jpg', 'videos/0117-KgI0tqW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3305', 'barbell thruster', 'shoulders', 'shoulders', 'barbell', 'Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip. Lower into a squat position by bending your knees and pushing your hips back. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead. Lower the barbell back to shoulder height as you lower back into the squat position. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono. Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza. Baja la barra de nuevo a la altura de los hombros mientras vuelves a bajar a la posición de sentadilla. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","glutes","hamstrings","core"]'::jsonb, 'delts', 'images/3305-f7Y9eDZ.jpg', 'videos/3305-f7Y9eDZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0120', 'barbell upright row', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta y el core activado, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/0120-UDlhcO8.jpg', 'videos/0120-UDlhcO8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0119', 'barbell upright row v. 2', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/0119-83HoW9X.jpg', 'videos/0119-83HoW9X.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0121', 'barbell upright row v. 3', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo el core activado y la espalda recta, exhala mientras levantas la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/0121-fI18Rbc.jpg', 'videos/0121-fI18Rbc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0122', 'barbell wide bench press', 'chest', 'chest', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Lower the barbell slowly towards your chest, keeping your elbows slightly flared out. Pause for a moment when the barbell touches your chest, then push it back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos ligeramente abiertos hacia afuera. Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0122-JsKq9so.jpg', 'videos/0122-JsKq9so.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1258', 'barbell wide reverse grip bench press', 'chest', 'chest', 'barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight. Pause for a moment when the barbell touches your chest, then push it back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo y las muñecas rectas. Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1258-945zpRg.jpg', 'videos/1258-945zpRg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0124', 'barbell wide squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0124-s7HX1BY.jpg', 'videos/0124-s7HX1BY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0123', 'barbell wide-grip upright row', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/0123-RgJDRR1.jpg', 'videos/0123-RgJDRR1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0126', 'barbell wrist curl', 'lower arms', 'lower arms', 'barbell', 'Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip. Allow the barbell to roll down to your fingertips, keeping your wrists straight. Slowly curl the barbell up towards your forearms by flexing your wrists. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino. Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas. Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0126-82LxxkW.jpg', 'videos/0126-82LxxkW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0125', 'barbell wrist curl v. 2', 'lower arms', 'lower arms', 'barbell', 'Sit on a bench with your feet flat on the ground and your knees bent. Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the barbell towards your forearms. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0125-6kSxYnw.jpg', 'videos/0125-6kSxYnw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0127', 'barbell zercher squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position. Keep your knees in line with your toes and your weight in your heels. Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra en el pliegue de los codos, con las manos agarrando la barra para mayor estabilidad. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/0127-LSTChY9.jpg', 'videos/0127-LSTChY9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3212', 'basic toe touch (male)', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and your arms by your sides. Bend forward at the waist, keeping your back straight and your knees slightly bent. Reach down towards your toes with your hands, keeping your legs as straight as possible. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende las manos hacia las puntas de los pies, manteniendo las piernas lo más rectas posible. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","calves"]'::jsonb, 'glutes', 'images/3212-BbfB8Gb.jpg', 'videos/3212-BbfB8Gb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0128', 'battling ropes', 'shoulders', 'shoulders', 'rope', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold one end of the rope in each hand, with your palms facing each other. Raise your arms to shoulder height, keeping your elbows slightly bent. Begin making alternating waves with the ropes by rapidly raising and lowering each arm. Continue for the desired duration or number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta un extremo de la cuerda en cada mano, con las palmas mirándose entre sí. Levanta los brazos hasta la altura de los hombros, manteniendo los codos ligeramente flexionados. Comienza a hacer ondas alternas con las cuerdas, levantando y bajando rápidamente cada brazo. Continúa durante el tiempo o el número de repeticiones deseado.', 'forearms', '["forearms","core"]'::jsonb, 'delts', 'images/0128-RJa4tCo.jpg', 'videos/0128-RJa4tCo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3360', 'bear crawl', 'cardio', 'cardio', 'body weight', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips. Lift your knees slightly off the ground, keeping your back flat and your core engaged. Move your right hand and left foot forward simultaneously, followed by your left hand and right foot. Continue crawling forward, alternating your hand and foot movements. Maintain a steady pace and keep your core tight throughout the exercise. Continue for the desired distance or time.', 'Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas. Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado. Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho. Continúa avanzando a gatas, alternando los movimientos de manos y pies. Mantén un ritmo constante y el core firme durante todo el ejercicio. Continúa durante la distancia o el tiempo deseado.', 'core', '["core","shoulders","triceps"]'::jsonb, 'cardiovascular system', 'images/3360-0Yz8WdV.jpg', 'videos/3360-0Yz8WdV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1259', 'behind head chest stretch', 'chest', 'chest', 'assisted', 'Stand tall with your feet shoulder-width apart. Interlace your fingers behind your head with your elbows pointing outwards. Slowly squeeze your shoulder blades together and push your chest forward. Hold the stretch for 15-30 seconds. Release the stretch and repeat as desired.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Entrelaza los dedos detrás de la cabeza con los codos apuntando hacia afuera. Junta lentamente los omóplatos y empuja el pecho hacia adelante. Mantén el estiramiento durante 15-30 segundos. Suelta el estiramiento y repite cuantas veces lo desees.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1259-QoHIhPl.jpg', 'videos/1259-QoHIhPl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0129', 'bench dip (knees bent)', 'upper arms', 'upper arms', 'body weight', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips. Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas. Desliza los glúteos fuera del banco y estira las piernas frente a ti, manteniendo los talones en el suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0129-RrLske5.jpg', 'videos/0129-RrLske5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1399', 'bench dip on floor', 'upper arms', 'upper arms', 'body weight', 'Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Lower your body by bending your elbows until your upper arms are parallel to the floor. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1399-9RT8oQW.jpg', 'videos/1399-9RT8oQW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0130', 'bench hip extension', 'upper legs', 'upper legs', 'body weight', 'Sit on a bench with your back against the bench and your feet flat on the ground. Place your hands on the bench for support. Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda contra el banco y los pies planos en el suelo. Coloca las manos sobre el banco para apoyarte. Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'glutes', 'images/0130-u27Kcdz.jpg', 'videos/0130-u27Kcdz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3019', 'bench pull-ups', 'back', 'back', 'body weight', 'Position yourself under a bar or a sturdy horizontal surface that is at chest height. Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your body straight. Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows. Continue pulling until your chin is above the bar or surface. Lower yourself back down to the starting position with control. Repeat for the desired number of repetitions.', 'Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho. Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros. Cuélgate con los brazos completamente extendidos y el cuerpo recto. Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos. Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie. Baja de nuevo a la posición inicial con control. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/3019-mExgrF9.jpg', 'videos/3019-mExgrF9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3639', 'bent knee lying twist (male)', 'upper legs', 'upper legs', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms out to the sides, perpendicular to your body. Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees. Pause for a moment, then engage your core and slowly lift your knees back to the starting position. Repeat the movement to the other side. Continue alternating sides for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos hacia los lados, perpendiculares al cuerpo. Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas. Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial. Repite el movimiento hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'glutes', 'images/3639-6sYyrRX.jpg', 'videos/3639-6sYyrRX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1770', 'biceps leg concentration curl', 'upper arms', 'upper arms', 'body weight', 'Sit on a bench with your legs spread apart and your feet flat on the ground. Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee. With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con las piernas separadas y los pies planos en el suelo. Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla. Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto. Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1770-sJFIDIp.jpg', 'videos/1770-sJFIDIp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0139', 'biceps narrow pull-ups', 'upper arms', 'upper arms', 'body weight', 'Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart. Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body. Pause for a moment at the top, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/0139-50BETrz.jpg', 'videos/0139-50BETrz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0140', 'biceps pull-up', 'upper arms', 'upper arms', 'body weight', 'Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart. Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar. Pause at the top of the movement, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra. Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/0140-guT8YnS.jpg', 'videos/0140-guT8YnS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0137', 'body-up', 'upper arms', 'upper arms', 'body weight', 'Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward. Extend your legs out in front of you, keeping your heels on the ground and your body straight. Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground. Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante. Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto. Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo. Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0137-U6G2gk9.jpg', 'videos/0137-U6G2gk9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3543', 'bodyweight drop jump squat', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and pushing your hips back. Jump up explosively, extending your hips, knees, and ankles. While in mid-air, quickly bring your feet together. Land softly on the balls of your feet and immediately drop back into a squat position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos. Mientras estás en el aire, junta rápidamente los pies. Aterriza suavemente sobre las puntas de los pies y de inmediato vuelve a bajar a una posición de sentadilla. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3543-wfotm7S.jpg', 'videos/3543-wfotm7S.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3544', 'bodyweight incline side plank', 'waist', 'waist', 'body weight', 'Start by lying on your side with your legs extended and stacked on top of each other. Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet. Hold this position for the desired amount of time. Lower your hips back down to the ground and repeat on the other side.', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Mantén esta posición durante el tiempo deseado. Baja las caderas de nuevo al suelo y repite hacia el otro lado.', 'obliques', '["obliques","shoulders"]'::jsonb, 'abs', 'images/3544-5VXmnV5.jpg', 'videos/3544-5VXmnV5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1771', 'bodyweight kneeling triceps extension', 'upper arms', 'upper arms', 'body weight', 'Kneel down on the ground with your knees hip-width apart. Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward. Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels. Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides. Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas. Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante. Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones. Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo. Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest"]'::jsonb, 'triceps', 'images/1771-s0HKO2I.jpg', 'videos/1771-s0HKO2I.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1769', 'bodyweight side lying biceps curl', 'upper arms', 'upper arms', 'body weight', 'Lie on your side with your legs extended and your head supported by your arm. Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo. Mantén el brazo superior junto al cuerpo y flexiona el codo para llevar el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1769-gscGLOU.jpg', 'videos/1769-gscGLOU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3168', 'bodyweight squatting row', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended. Lower your body into a squat position, keeping your back straight and your knees behind your toes. From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando un objeto resistente o un entrenador de suspensión con los brazos extendidos. Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies. Desde la posición de sentadilla, tira del cuerpo hacia arriba en dirección al objeto o al entrenador de suspensión, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/3168-3xK09Sk.jpg', 'videos/3168-3xK09Sk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3167', 'bodyweight squatting row (with towel)', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down. Bend your knees and lower your body into a squat position, keeping your back straight and your chest up. As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una toalla frente a ti con las palmas hacia abajo. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Mientras bajas a la sentadilla, tira simultáneamente de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte más baja de la sentadilla, luego vuelve lentamente a la posición inicial mientras extiendes los brazos. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/3167-BReCuOn.jpg', 'videos/3167-BReCuOn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1373', 'bodyweight standing calf raise', 'lower legs', 'lower legs', 'body weight', 'Stand with your feet shoulder-width apart, toes pointing forward. Place your hands on a wall or stable surface for balance. Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Coloca las manos sobre una pared o superficie estable para mantener el equilibrio. Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'ankles', '["ankles","feet"]'::jsonb, 'calves', 'images/1373-bJYHBIN.jpg', 'videos/1373-bJYHBIN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3156', 'bodyweight standing close-grip one arm row', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip. Bend forward at the hips, keeping your back straight and your core engaged. Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en una mano con agarre neutro. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/3156-v2DfH14.jpg', 'videos/3156-v2DfH14.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3158', 'bodyweight standing close-grip row', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and knees slightly bent. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arms straight in front of you, gripping the bar or handles with a close grip. Pull the bar or handles towards your body, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende los brazos rectos frente a ti, sujetando la barra o las agarraderas con un agarre cerrado. Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos. Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/3158-tig3PXb.jpg', 'videos/3158-tig3PXb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3162', 'bodyweight standing one arm row', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand. Bend forward at the hips, keeping your back straight and your core engaged. Let the dumbbell hang straight down in front of you, with your arm fully extended. Pull the dumbbell up towards your chest, keeping your elbow close to your body. Squeeze your shoulder blades together at the top of the movement. Lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna con una mano. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que la mancuerna cuelgue recta frente a ti, con el brazo completamente extendido. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/3162-xbkPfaw.jpg', 'videos/3162-xbkPfaw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3161', 'bodyweight standing one arm row (with towel)', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand. Bend forward at the hips, keeping your back straight and your core engaged. Pull the towel towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the towel back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/3161-O4oIqQD.jpg', 'videos/3161-O4oIqQD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3166', 'bodyweight standing row', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and knees slightly bent. Grasp a bar or handles with an overhand grip, palms facing down. Keep your back straight and core engaged. Pull the bar or handles towards your body, squeezing your shoulder blades together. Pause for a moment at the top of the movement. Slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo. Mantén la espalda recta y el core activado. Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/3166-wd4ds3s.jpg', 'videos/3166-wd4ds3s.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3165', 'bodyweight standing row (with towel)', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and hold a towel in front of you with both hands. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pull the towel towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una toalla frente a ti con ambas manos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Tira de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/3165-uTv34oq.jpg', 'videos/3165-uTv34oq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0138', 'bottoms-up', 'waist', 'waist', 'body weight', 'Lie flat on your back with your legs extended and your arms by your sides. Bend your knees and bring them towards your chest, keeping your feet off the ground. Engaging your abs, lift your hips off the ground, bringing your knees towards your head. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo. Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/0138-CI6baTY.jpg', 'videos/0138-CI6baTY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1374', 'box jump down with one leg stabilization', 'lower legs', 'lower legs', 'body weight', 'Stand in front of a box or platform with your feet shoulder-width apart. Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge. Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground. Hold this position for a few seconds, engaging your calf muscles to maintain balance. Slowly step down with the foot that is on the box, returning to the starting position. Repeat the exercise with the other leg.', 'Ponte de pie frente a una caja o plataforma con los pies separados a la altura de los hombros. Flexiona las rodillas y salta sobre la caja, aterrizando suavemente con un pie sobre la caja y el otro pie colgando del borde. Estabilízate sobre la caja con el pie que está sobre ella, mientras mantienes el otro pie fuera del suelo. Mantén esta posición durante unos segundos, activando los músculos de la pantorrilla para conservar el equilibrio. Baja lentamente con el pie que está sobre la caja, volviendo a la posición inicial. Repite el ejercicio con la otra pierna.', 'quadriceps', '["quadriceps","hamstrings","glutes"]'::jsonb, 'calves', 'images/1374-iPm26QU.jpg', 'videos/1374-iPm26QU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2466', 'bridge - mountain climber (cross body)', 'waist', 'waist', 'body weight', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow. Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow. Continue alternating sides, moving at a controlled pace. Keep your hips level and avoid lifting your hips too high or sagging them too low. Maintain a steady breathing pattern throughout the exercise. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo. Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho. Continúa alternando los lados, moviéndote a un ritmo controlado. Mantén las caderas niveladas y evita levantarlas demasiado alto o dejarlas caer demasiado bajo. Mantén un patrón de respiración constante durante todo el ejercicio. Repite el número de repeticiones deseado.', 'glutes', '["glutes","quadriceps","hamstrings","shoulders","triceps"]'::jsonb, 'abs', 'images/2466-9c6T1YX.jpg', 'videos/2466-9c6T1YX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1160', 'burpee', 'cardio', 'cardio', 'body weight', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you. Kick your feet back into a push-up position. Perform a push-up, keeping your body in a straight line. Jump your feet back into the squat position. Jump up explosively, reaching your arms overhead. Land softly and immediately lower back into a squat position to begin the next repetition.', 'Comienza de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y colocando las manos en el suelo frente a ti. Lleva los pies hacia atrás de una patada hasta una posición de flexión de brazos. Realiza una flexión de brazos, manteniendo el cuerpo en línea recta. Salta con los pies de vuelta a la posición de sentadilla. Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza. Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.', 'quadriceps', '["quadriceps","hamstrings","calves","shoulders","chest"]'::jsonb, 'cardiovascular system', 'images/1160-dK9394r.jpg', 'videos/1160-dK9394r.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0870', 'butt-ups', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands by your sides, palms facing down. Engaging your abs, lift your legs off the ground, bringing your knees towards your chest. At the top of the movement, squeeze your abs and pause for a moment. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados, con las palmas hacia abajo. Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho. En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0870-qcNN2FN.jpg', 'videos/0870-qcNN2FN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1494', 'butterfly yoga pose', 'upper legs', 'upper legs', 'body weight', 'Sit on the floor with your legs extended in front of you. Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides. Hold onto your ankles or feet with your hands. Sit up tall and lengthen your spine. Gently press your knees down towards the floor, feeling a stretch in your inner thighs. Hold this position for a few breaths. To release, slowly bring your knees back up and extend your legs.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados. Sujétate los tobillos o los pies con las manos. Siéntate erguido y alarga la columna. Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos. Mantén esta posición durante unas cuantas respiraciones. Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas.', 'hamstrings', '["hamstrings","groin"]'::jsonb, 'adductors', 'images/1494-bWlZvXh.jpg', 'videos/1494-bWlZvXh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0148', 'cable alternate shoulder press', 'shoulders', 'shoulders', 'cable', 'Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip. Position your hands at shoulder height, with your palms facing forward. Keep your core engaged and your back straight. Press one handle up and forward until your arm is fully extended. Pause for a moment at the top, then slowly lower the handle back to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas de la máquina de cable con agarre prono. Coloca las manos a la altura de los hombros, con las palmas mirando hacia adelante. Mantén el core activado y la espalda recta. Empuja una agarradera hacia arriba y hacia adelante hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0148-KHPZL0b.jpg', 'videos/0148-KHPZL0b.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0149', 'cable alternate triceps extension', 'upper arms', 'upper arms', 'cable', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle. Keep your upper arm stationary and extend your forearm backward, fully straightening your arm. Pause for a moment, then slowly return to the starting position. Repeat with your left arm. Continue alternating arms for the desired number of repetitions.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados. Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0149-Gchi5Tr.jpg', 'videos/0149-Gchi5Tr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3235', 'cable assisted inverse leg curl', 'upper legs', 'upper legs', 'cable', 'Adjust the cable machine so that the ankle attachment is at the lowest setting. Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles. Hold onto the handles of the bench for stability. Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees. Pause for a moment at the top of the movement, squeezing your hamstrings. Inhale and slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable de modo que el accesorio para el tobillo quede en la posición más baja. Túmbate boca abajo en el banco con las piernas rectas y el accesorio para el tobillo sujeto a los tobillos. Sujétate de las agarraderas del banco para mantener la estabilidad. Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas. Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales. Inhala y baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","calves"]'::jsonb, 'hamstrings', 'images/3235-zHEpuuc.jpg', 'videos/3235-zHEpuuc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0150', 'cable bar lateral pulldown', 'back', 'back', 'cable', 'Adjust the cable pulley to a high position and attach a straight bar. Sit facing the cable machine with your feet flat on the ground and your knees slightly bent. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and keep your chest up, maintaining a slight arch in your lower back. Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la polea del cable a una posición alta y coloca una barra recta. Siéntate frente a la máquina de cable con los pies planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar. Tira de la barra hacia el pecho, guiando el movimiento con los codos y juntando los omóplatos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/0150-eYnzaCm.jpg', 'videos/0150-eYnzaCm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0151', 'cable bench press', 'chest', 'chest', 'cable', 'Adjust the cable machine to chest height and attach the handles. Stand facing away from the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and step forward to create tension in the cables. Position your feet firmly on the ground and engage your core. Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle. Push the handles forward, extending your arms fully in front of you. Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables. Coloca los pies firmemente en el suelo y activa el core. Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados. Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti. Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0151-7xI5MXA.jpg', 'videos/0151-7xI5MXA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1630', 'cable close grip curl', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an underhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Exhale and curl the bar up towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1630-BCGQ6J5.jpg', 'videos/1630-BCGQ6J5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1631', 'cable concentration curl', 'upper arms', 'upper arms', 'cable', 'Sit on a bench or chair with your feet flat on the floor and your knees slightly bent. Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh. Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps. Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco o silla con los pies planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con agarre supino y apoya el codo en la parte interna del muslo. Manteniendo el brazo superior quieto, exhala y flexiona la agarradera del cable hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta del movimiento, luego inhala y baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1631-NvfE43H.jpg', 'videos/1631-NvfE43H.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0152', 'cable concentration extension (on knee)', 'upper arms', 'upper arms', 'cable', 'Sit on a bench or chair with your knees bent and feet flat on the ground. Hold the cable handle with your right hand and place your elbow on the inside of your right knee. Extend your arm fully, keeping your elbow stationary and close to your knee. Pause for a moment at the top, then slowly lower your arm back to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo. Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha. Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/0152-Db7eEgw.jpg', 'videos/0152-Db7eEgw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0153', 'cable cross-over lateral pulldown', 'back', 'back', 'cable', 'Attach a cable handle to each side of a cable machine at shoulder height. Stand in the middle of the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and step back to create tension in the cables. Lean forward slightly from the hips, keeping your back straight and your chest up. Pull the handles down and across your body, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros. Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables. Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Tira de las agarraderas hacia abajo y a través del cuerpo, juntando los omóplatos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/0153-OQ1otBN.jpg', 'videos/0153-OQ1otBN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0154', 'cable cross-over revers fly', 'shoulders', 'shoulders', 'cable', 'Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine. Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart. Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged. With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions.', 'Coloca una agarradera en D en cada cable de polea baja y ponte de pie en el centro de la máquina de cable cruzado. Sujeta las agarraderas con agarre prono (palmas hacia abajo) y da un paso hacia adelante, colocando los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen activado. Con los brazos extendidos hacia los lados y ligeramente flexionados en los codos, exhala y junta los omóplatos mientras tiras de los cables hacia atrás y hacia arriba en un movimiento de apertura inversa. Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'rhomboids', '["rhomboids","trapezius"]'::jsonb, 'delts', 'images/0154-aqvSOQE.jpg', 'videos/0154-aqvSOQE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0155', 'cable cross-over variation', 'chest', 'chest', 'cable', 'Adjust the cable pulleys to chest height. Stand in the center of the cable machine with one foot in front of the other. Grasp the handles with your palms facing down and your arms extended out to the sides. Take a step forward, keeping your arms slightly bent. With a slight bend in your elbows, bring your hands together in front of your chest. Pause for a moment, then slowly return your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta las poleas del cable a la altura del pecho. Ponte de pie en el centro de la máquina de cable con un pie delante del otro. Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados. Da un paso hacia adelante, manteniendo los brazos ligeramente flexionados. Con una ligera flexión en los codos, junta las manos frente al pecho. Haz una pausa breve, luego vuelve lentamente los brazos a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0155-0CXGHya.jpg', 'videos/0155-0CXGHya.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0868', 'cable curl', 'upper arms', 'upper arms', 'cable', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable attachment with an underhand grip, palms facing up. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the cable attachment towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable attachment back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con agarre supino, palmas hacia arriba. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0868-G08RZcQ.jpg', 'videos/0868-G08RZcQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0157', 'cable deadlift', 'upper legs', 'upper legs', 'cable', 'Stand facing the cable machine with your feet shoulder-width apart. Bend at the hips and knees, lowering your torso until your back is parallel to the ground. Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back. Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight. Pause for a moment at the top, then slowly lower the cable handles back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo. Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás. Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie. Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","lower back"]'::jsonb, 'glutes', 'images/0157-eGDudUV.jpg', 'videos/0157-eGDudUV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0158', 'cable decline fly', 'chest', 'chest', 'cable', 'Adjust the cable machine to a decline position. Stand facing away from the machine with your feet shoulder-width apart. Hold the handles with your palms facing forward and your arms extended straight out in front of you. Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion. Pause for a moment at the fully extended position, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable a una posición declinada. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti. Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado. Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0158-7saC5zz.jpg', 'videos/0158-7saC5zz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1260', 'cable decline one arm press', 'chest', 'chest', 'cable', 'Adjust the cable machine to a decline position. Stand facing away from the machine and grab the handle with one hand. Position yourself with your back against the decline bench and your arm extended straight in front of you. Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary. Pause for a moment at the bottom, then push the handle back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ajusta la máquina de cable a una posición declinada. Ponte de pie de espaldas a la máquina y sujeta la agarradera con una mano. Colócate con la espalda contra el banco declinado y el brazo extendido recto frente a ti. Flexiona el codo y baja la agarradera hacia el pecho, manteniendo el brazo superior quieto. Haz una pausa breve en la parte más baja, luego empuja la agarradera de vuelta hacia la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1260-KHGNa16.jpg', 'videos/1260-KHGNa16.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1261', 'cable decline press', 'chest', 'chest', 'cable', 'Adjust the cable machine to a decline position. Sit on the decline bench facing the cable machine. Grasp the handles with an overhand grip and position them at chest level. Keep your feet flat on the ground and your back firmly against the bench. Exhale and push the handles away from your body, extending your arms fully. Pause for a moment at the end of the movement, squeezing your chest muscles. Inhale and slowly return the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable a una posición declinada. Siéntate en el banco declinado frente a la máquina de cable. Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho. Mantén los pies planos en el suelo y la espalda firmemente apoyada en el banco. Exhala y empuja las agarraderas alejándolas del cuerpo, extendiendo completamente los brazos. Haz una pausa breve al final del movimiento, contrayendo los músculos del pecho. Inhala y vuelve lentamente las agarraderas a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1261-2Pya1cP.jpg', 'videos/1261-2Pya1cP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0159', 'cable decline seated wide-grip row', 'back', 'back', 'cable', 'Sit on the decline bench facing the cable machine with your feet securely placed on the footrests. Grasp the cable attachment with a wide overhand grip, palms facing down. Lean back slightly, keeping your back straight and your core engaged. Pull the cable towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el banco declinado frente a la máquina de cable con los pies firmemente colocados en los reposapiés. Sujeta el accesorio del cable con un agarre prono amplio, palmas hacia abajo. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado. Tira del cable hacia la parte inferior del pecho, juntando los omóplatos. Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0159-kesXOpB.jpg', 'videos/0159-kesXOpB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1632', 'cable drag curl', 'upper arms', 'upper arms', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended. Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1632-dXz8zjF.jpg', 'videos/1632-dXz8zjF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0160', 'cable floor seated wide-grip row', 'back', 'back', 'cable', 'Sit on the floor with your legs extended and your back straight. Attach a cable handle to a low pulley and position the cable machine behind you. Grasp the handle with a wide overhand grip, palms facing down. Lean back slightly, keeping your back straight and your chest lifted. Pull the handle towards your waist, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the handle back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas y la espalda recta. Coloca una agarradera de cable en una polea baja y ubica la máquina de cable detrás de ti. Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado. Tira de la agarradera hacia la cintura, juntando los omóplatos. Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0160-veXwo0D.jpg', 'videos/0160-veXwo0D.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0161', 'cable forward raise', 'shoulders', 'shoulders', 'cable', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you. Keeping your arms straight, raise the cable handle up to shoulder level. Pause for a moment at the top, then slowly lower the cable handle back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti. Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","forearms"]'::jsonb, 'delts', 'images/0161-hvHhCv8.jpg', 'videos/0161-hvHhCv8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0162', 'cable front raise', 'shoulders', 'shoulders', 'cable', 'Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip. Keep your back straight and your core engaged. Raise the cable handle in front of you, keeping your arms straight and your palms facing down. Continue lifting until your arms are parallel to the floor. Pause for a moment at the top, then slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que los brazos queden paralelos al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","forearms"]'::jsonb, 'delts', 'images/0162-u2X71Np.jpg', 'videos/0162-u2X71Np.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0164', 'cable front shoulder raise', 'shoulders', 'shoulders', 'cable', 'Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip. Keep your back straight and your core engaged. Raise the cable handle in front of you, keeping your arms straight and your palms facing down. Continue lifting until your arms are parallel to the floor. Pause for a moment at the top, then slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que los brazos queden paralelos al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","biceps"]'::jsonb, 'delts', 'images/0164-mTT3KLn.jpg', 'videos/0164-mTT3KLn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0165', 'cable hammer curl (with rope)', 'upper arms', 'upper arms', 'cable', 'Stand upright with your feet shoulder-width apart and a slight bend in your knees. Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the cable rope attachment back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando el accesorio de cuerda del cable hasta que los bíceps estén completamente contraídos y la cuerda esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente el accesorio de cuerda del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0165-HPlPoQA.jpg', 'videos/0165-HPlPoQA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1722', 'cable high pulley overhead tricep extension', 'upper arms', 'upper arms', 'cable', 'Attach a rope to a high pulley and stand facing away from the machine. Grasp the rope with both hands and extend your arms overhead. Keep your elbows close to your head and your upper arms stationary. Slowly lower the rope behind your head by bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Coloca una cuerda en una polea alta y ponte de pie de espaldas a la máquina. Sujeta la cuerda con ambas manos y extiende los brazos por encima de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1722-1xHyxys.jpg', 'videos/1722-1xHyxys.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0167', 'cable high row (kneeling)', 'back', 'back', 'cable', 'Attach a straight bar to a cable machine at chest height. Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart. Sit back on your heels, keeping your back straight and your core engaged. Pull the bar towards your upper abdomen, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a una máquina de cable a la altura del pecho. Ponte de rodillas frente a la máquina de cable y agarra la barra con un agarre prono, con las manos separadas a la altura de los hombros. Siéntate sobre los talones, manteniendo la espalda recta y el core activado. Jala la barra hacia la parte superior del abdomen, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte más alta del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/0167-ZSJNetl.jpg', 'videos/0167-ZSJNetl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0168', 'cable hip adduction', 'upper legs', 'upper legs', 'cable', 'Attach the ankle cuff to your ankle and stand facing the cable machine. Position yourself far enough away from the machine so that there is tension on the cable. Place your hands on the machine for support. Keeping your leg straight, slowly move your leg across your body towards the midline. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta el manguito de tobillo a tu tobillo y ponte de pie frente a la máquina de cable. Colócate lo suficientemente alejado de la máquina para que haya tensión en el cable. Coloca las manos sobre la máquina para apoyarte. Manteniendo la pierna recta, mueve lentamente la pierna por delante del cuerpo hacia la línea media. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","quadriceps"]'::jsonb, 'adductors', 'images/0168-hBGWILP.jpg', 'videos/0168-hBGWILP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0169', 'cable incline bench press', 'chest', 'chest', 'cable', 'Adjust the bench to a 45-degree incline. Attach the cable handles to the high pulleys. Sit on the bench facing the cable machine with your feet flat on the ground. Grasp the handles with an overhand grip and bring them to shoulder height. Push the handles forward and upward until your arms are fully extended. Pause for a moment, then slowly lower the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el banco a una inclinación de 45 grados. Sujeta las agarraderas del cable a las poleas altas. Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta las agarraderas con un agarre prono y llévalas a la altura de los hombros. Empuja las agarraderas hacia adelante y hacia arriba hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego baja lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0169-Vh0GsK4.jpg', 'videos/0169-Vh0GsK4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1318', 'cable incline bench row', 'back', 'back', 'cable', 'Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley. Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent. Grasp the cable handle with an overhand grip and extend your arms fully in front of you. Lean forward from your hips while keeping your back straight and your core engaged. Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows. Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados y sujeta una agarradera de cable a la polea baja. Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con un agarre prono y extiende los brazos completamente frente a ti. Inclínate hacia adelante desde las caderas manteniendo la espalda recta y el core activado. Jala la agarradera del cable hacia el pecho retrayendo los omóplatos y flexionando los codos. Aprieta los músculos de la espalda en la parte más alta del movimiento y luego extiende lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rear deltoids"]'::jsonb, 'upper back', 'images/1318-yaMIo4D.jpg', 'videos/1318-yaMIo4D.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0171', 'cable incline fly', 'chest', 'chest', 'cable', 'Adjust the cable machine to a low position and attach the handles. Sit on an incline bench with your back against the pad and feet flat on the floor. Grasp the handles with an overhand grip and extend your arms straight out in front of you. Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion. Pause for a moment at the fully extended position, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable a una posición baja y sujeta las agarraderas. Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado. Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0171-tBWXbIT.jpg', 'videos/0171-tBWXbIT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0170', 'cable incline fly (on stability ball)', 'chest', 'chest', 'cable', 'Set up a stability ball at an incline angle. Attach the cable handles to the high pulleys of a cable machine. Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground. Grasp the cable handles with an overhand grip, palms facing forward. Lean forward slightly, keeping your back straight and core engaged. With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows. Continue the motion until your arms are parallel to the ground. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Coloca un balón de estabilidad en un ángulo inclinado. Sujeta las agarraderas del cable a las poleas altas de una máquina de cable. Siéntate sobre el balón de estabilidad de espaldas a la máquina, con los pies firmemente apoyados en el suelo. Sujeta las agarraderas del cable con un agarre prono, con las palmas hacia adelante. Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado. Con un movimiento controlado, lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Continúa el movimiento hasta que los brazos queden paralelos al suelo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0170-27NNGFr.jpg', 'videos/0170-27NNGFr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0172', 'cable incline pushdown', 'back', 'back', 'cable', 'Attach a straight bar to a high pulley cable machine. Stand facing away from the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart. Lean forward slightly and keep your back straight. Pull the bar down towards your thighs by extending your elbows. Pause for a moment at the bottom, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Inclínate ligeramente hacia adelante y mantén la espalda recta. Jala la barra hacia abajo en dirección a tus muslos extendiendo los codos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'lats', 'images/0172-1PK5Uo3.jpg', 'videos/0172-1PK5Uo3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0173', 'cable incline triceps extension', 'upper arms', 'upper arms', 'cable', 'Adjust the cable machine to a low pulley position. Attach a straight bar to the cable. Stand facing away from the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip and extend your arms straight overhead. Lean forward slightly, keeping your back straight and core engaged. Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable a una posición de polea baja. Sujeta una barra recta al cable. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono y extiende los brazos rectos por encima de la cabeza. Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado. Flexiona los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0173-Hx1WC8I.jpg', 'videos/0173-Hx1WC8I.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0174', 'cable judo flip', 'waist', 'waist', 'cable', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands at chest level, palms facing down. Engage your core and rotate your torso to the right, pulling the cable across your body. As you rotate, pivot your back foot and allow your hips to rotate naturally. Extend your arms fully and finish the movement by flipping the cable handle over your shoulder. Return to the starting position by reversing the movement, rotating your torso back to the center. Repeat the movement on the opposite side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo. Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo. Mientras rotas, gira el pie de atrás y permite que las caderas roten de forma natural. Extiende los brazos completamente y termina el movimiento llevando la agarradera del cable por encima del hombro. Vuelve a la posición inicial revirtiendo el movimiento, rotando el torso de regreso al centro. Repite el movimiento en el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","shoulders"]'::jsonb, 'abs', 'images/0174-MvQPqVW.jpg', 'videos/0174-MvQPqVW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0860', 'cable kickback', 'upper arms', 'upper arms', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Hold the cable handle with your right hand and step back to create tension in the cable. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Keep your upper arm close to your body and your elbow bent at a 90-degree angle. Extend your forearm backward, straightening your arm fully. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados. Extiende el antebrazo hacia atrás, enderezando el brazo por completo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0860-HEJ6DIX.jpg', 'videos/0860-HEJ6DIX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0175', 'cable kneeling crunch', 'waist', 'waist', 'cable', 'Attach a rope handle to a high pulley and kneel down facing away from the machine. Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides. Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina. Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados. Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0175-WW95auq.jpg', 'videos/0175-WW95auq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3697', 'cable kneeling rear delt row (with rope) (male)', 'shoulders', 'shoulders', 'cable', 'Attach a rope handle to a low cable pulley and kneel down facing the machine. Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you. Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades. Squeeze your shoulder blades together at the end of the movement and hold for a brief pause. Slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una agarradera de cuerda a una polea baja y ponte de rodillas frente a la máquina. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y extiende los brazos completamente frente a ti. Manteniendo la espalda recta y el core activado, jala la cuerda hacia el cuerpo retrayendo los omóplatos. Aprieta los omóplatos al final del movimiento y mantén la posición por una breve pausa. Libera lentamente la tensión y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids","biceps"]'::jsonb, 'delts', 'images/3697-G61cXLk.jpg', 'videos/3697-G61cXLk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0176', 'cable kneeling triceps extension', 'upper arms', 'upper arms', 'cable', 'Attach a rope handle to a high pulley and kneel down facing the cable machine. Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head. Keep your elbows close to your head and your upper arms stationary throughout the exercise. Extend your forearms by contracting your triceps until your arms are fully extended. Pause for a moment, then slowly return to the starting position by bending your elbows. Repeat for the desired number of repetitions.', 'Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas frente a la máquina de cable. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y lleva las manos a los lados de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio. Extiende los antebrazos contrayendo los tríceps hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego vuelve lentamente a la posición inicial flexionando los codos. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0176-KWdF2JI.jpg', 'videos/0176-KWdF2JI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2330', 'cable lat pulldown full range of motion', 'back', 'back', 'cable', 'Sit on the lat pulldown machine with your knees positioned under the pads. Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and keep your chest up, maintaining a slight arch in your lower back. Pull the bar down towards your upper chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de jalón al pecho con las rodillas colocadas debajo de las almohadillas. Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/2330-LEprlgG.jpg', 'videos/2330-LEprlgG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0177', 'cable lateral pulldown (with rope attachment)', 'back', 'back', 'cable', 'Attach a rope attachment to the cable machine at a high position. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with an overhand grip, palms facing each other. Keep your back straight and lean slightly back. Pull the rope down towards your sides, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement. Slowly release the tension and allow the rope to return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta un accesorio de cuerda a la máquina de cable en una posición alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala la cuerda hacia los costados, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento. Libera lentamente la tensión y permite que la cuerda vuelva a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0177-CuaWCmC.jpg', 'videos/0177-CuaWCmC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2616', 'cable lateral pulldown with v-bar', 'back', 'back', 'cable', 'Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip. Adjust the knee pad so that your thighs are secured under it. Keep your back straight and lean back slightly. Pull the v-bar down towards your upper chest while keeping your elbows close to your body. Squeeze your back muscles at the bottom of the movement. Slowly return the v-bar to the starting position and repeat for the desired number of repetitions.', 'Siéntate en la máquina de jalón de cable y agarra el accesorio en V con un agarre prono. Ajusta la almohadilla de rodillas para que tus muslos queden asegurados debajo de ella. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala el accesorio en V hacia la parte superior del pecho manteniendo los codos cerca del cuerpo. Aprieta los músculos de la espalda en la parte baja del movimiento. Regresa lentamente el accesorio en V a la posición inicial y repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/2616-4c9BhzB.jpg', 'videos/2616-4c9BhzB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0178', 'cable lateral raise', 'shoulders', 'shoulders', 'cable', 'Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip. Keep your arms straight and your core engaged. Raise your arms out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono. Mantén los brazos rectos y el core activado. Levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","triceps"]'::jsonb, 'delts', 'images/0178-goJ6ezq.jpg', 'videos/0178-goJ6ezq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0179', 'cable low fly', 'chest', 'chest', 'cable', 'Attach the handles to the low pulleys of a cable machine and select an appropriate weight. Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows. Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body. Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles. Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout. Repeat for the desired number of repetitions.', 'Sujeta las agarraderas a las poleas bajas de una máquina de cable y selecciona un peso adecuado. Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados, manteniendo una ligera flexión en los codos. Manteniendo el control, lleva lentamente los brazos hacia adelante con un movimiento amplio, cruzándolos frente al cuerpo. Haz una pausa por un momento en el punto más alto del movimiento, sintiendo el estiramiento en los músculos del pecho. Invierte el movimiento y regresa lentamente los brazos a la posición inicial, manteniendo la tensión en los músculos del pecho durante todo el recorrido. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0179-FVmZVhk.jpg', 'videos/0179-FVmZVhk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0180', 'cable low seated row', 'back', 'back', 'cable', 'Sit on the machine with your feet flat on the footrests and your knees slightly bent. Grasp the handles with an overhand grip, palms facing down. Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0180-hvV79Si.jpg', 'videos/0180-hvV79Si.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1634', 'cable lying bicep curl', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to a low pulley cable machine. Lie face up on a flat bench with your feet flat on the ground. Grasp the bar with an underhand grip, hands shoulder-width apart. Extend your arms fully, keeping your elbows close to your sides. Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca una barra recta en una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Extiende los brazos por completo, manteniendo los codos cerca de los costados. Manteniendo la parte superior de los brazos inmóvil, exhala y curva la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1634-otqIxU4.jpg', 'videos/1634-otqIxU4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0182', 'cable lying close-grip curl', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to a low pulley cable machine. Lie face up on a flat bench with your feet flat on the ground. Grasp the bar with an underhand grip, hands shoulder-width apart. Extend your arms fully, keeping your elbows close to your sides. Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps. Pause for a moment at the top, squeezing your biceps. Slowly lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca una barra recta en una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Extiende los brazos por completo, manteniendo los codos cerca de los costados. Manteniendo la parte superior de los brazos inmóvil, curva la barra hacia el pecho contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Baja lentamente la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0182-61GrD55.jpg', 'videos/0182-61GrD55.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0184', 'cable lying extension pullover (with rope attachment)', 'back', 'back', 'cable', 'Attach a rope to a cable machine and set the pulley at the highest position. Lie down on a bench with your head towards the cable machine. Hold the rope with both hands and extend your arms straight up above your chest. Keeping your arms straight, slowly lower the rope behind your head while maintaining control. Pause for a moment at the bottom, then slowly raise the rope back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a una máquina de cable y coloca la polea en la posición más alta. Túmbate en un banco con la cabeza orientada hacia la máquina de cable. Sujeta la cuerda con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la cuerda detrás de la cabeza manteniendo el control. Haz una pausa por un momento en la parte baja y luego sube lentamente la cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'lats', 'images/0184-Q2Eu1Ax.jpg', 'videos/0184-Q2Eu1Ax.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0185', 'cable lying fly', 'chest', 'chest', 'cable', 'Attach the handles to the cables and lie flat on a bench with your feet flat on the ground. Hold the handles with your palms facing each other and your arms extended straight above your chest. Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo. Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho. Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0185-lJJ7Yq8.jpg', 'videos/0185-lJJ7Yq8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0186', 'cable lying triceps extension v. 2', 'upper arms', 'upper arms', 'cable', 'Attach a rope handle to a low pulley cable machine. Lie down on a flat bench facing up, with your head towards the cable machine. Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows. Pause for a moment at the bottom, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con la cabeza orientada hacia la máquina de cable. Sujeta la agarradera de cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos por encima del pecho. Manteniendo la parte superior de los brazos inmóvil, baja lentamente la agarradera de cuerda hacia la frente flexionando los codos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0186-uxJcFUU.jpg', 'videos/0186-uxJcFUU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0188', 'cable middle fly', 'chest', 'chest', 'cable', 'Attach cables to both sides of a cable machine at chest height. Stand in the center of the machine with one foot slightly in front of the other. Grasp the handles with an overhand grip and extend your arms out to the sides. Keep a slight bend in your elbows and maintain a slight forward lean. Engage your chest muscles and bring your arms forward in a sweeping motion. Pause for a moment at the center, then slowly return your arms back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta los cables a ambos lados de una máquina de cable a la altura del pecho. Ponte de pie en el centro de la máquina con un pie ligeramente delante del otro. Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados. Mantén una ligera flexión en los codos y conserva una leve inclinación hacia adelante. Activa los músculos del pecho y lleva los brazos hacia adelante con un movimiento amplio. Haz una pausa por un momento en el centro y luego regresa lentamente los brazos a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0188-xLYSdtg.jpg', 'videos/0188-xLYSdtg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0189', 'cable one arm bent over row', 'back', 'back', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the cable handle with one hand, palm facing inward, and extend your arm fully. Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest. Pause for a moment, then slowly extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la agarradera del cable con una mano, con la palma hacia adentro, y extiende el brazo por completo. Jala la agarradera del cable hacia el cuerpo, manteniendo el codo cerca del costado, hasta que la mano llegue a la parte baja del pecho. Haz una pausa por un momento y luego extiende lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0189-EIsE3u8.jpg', 'videos/0189-EIsE3u8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0190', 'cable one arm curl', 'upper arms', 'upper arms', 'cable', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip, palm facing up. Keep your elbow close to your side and slowly curl your forearm up towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba. Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0190-YTur5nR.jpg', 'videos/0190-YTur5nR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1262', 'cable one arm decline chest fly', 'chest', 'chest', 'cable', 'Attach a D-handle to a low pulley cable machine and set the bench to a decline angle. Lie down on the bench with your head towards the machine and grab the handle with your right hand. Extend your arm straight up above your chest, keeping a slight bend in your elbow. With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder. Pause for a moment, then reverse the motion and bring your arm back to the starting position. Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise.', 'Sujeta una agarradera en D a una máquina de cable con polea baja y coloca el banco en un ángulo declinado. Túmbate en el banco con la cabeza orientada hacia la máquina y agarra la agarradera con la mano derecha. Extiende el brazo recto por encima del pecho, manteniendo una ligera flexión en el codo. Con un movimiento controlado, baja el brazo hacia el lado hasta que la mano quede alineada con el hombro. Haz una pausa por un momento y luego invierte el movimiento para regresar el brazo a la posición inicial. Repite el número de repeticiones deseado y luego cambia al brazo izquierdo y repite el ejercicio.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1262-w4dLzSx.jpg', 'videos/1262-w4dLzSx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1263', 'cable one arm fly on exercise ball', 'chest', 'chest', 'cable', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground. Keep your elbow slightly bent and your palm facing forward. Slowly bring your arm across your body, squeezing your chest muscles. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y extiende el brazo hacia el lado, paralelo al suelo. Mantén el codo ligeramente flexionado y la palma hacia adelante. Lleva lentamente el brazo a través del cuerpo, apretando los músculos del pecho. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/1263-hHy8tQG.jpg', 'videos/1263-hHy8tQG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1264', 'cable one arm incline fly on exercise ball', 'chest', 'chest', 'cable', 'Sit on an exercise ball with your feet flat on the ground and your back against an incline bench. Hold a cable handle in one hand with your arm extended and palm facing inward. Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder. Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado. Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro. Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro. Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar el brazo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/1264-P14Dz9D.jpg', 'videos/1264-P14Dz9D.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1265', 'cable one arm incline press', 'chest', 'chest', 'cable', 'Adjust the cable machine to a low pulley position. Sit on an incline bench facing away from the cable machine. Grasp the handle with one hand and bring it up to shoulder height. Position your feet firmly on the ground and maintain a stable position. Press the handle forward and upward, extending your arm fully. Pause for a moment at the top, then slowly lower the handle back to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ajusta la máquina de cable a una posición de polea baja. Siéntate en un banco inclinado de espaldas a la máquina de cable. Sujeta la agarradera con una mano y llévala hasta la altura del hombro. Coloca los pies firmemente en el suelo y mantén una posición estable. Empuja la agarradera hacia adelante y hacia arriba, extendiendo el brazo por completo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/1265-GKEH6jj.jpg', 'videos/1265-GKEH6jj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1266', 'cable one arm incline press on exercise ball', 'chest', 'chest', 'cable', 'Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench. Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent. Press the cable handle forward and upward, extending your arm fully. Pause for a moment at the top, then slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado. Sujeta una agarradera del cable con una mano y coloca el brazo en un ángulo de 90 grados con el codo flexionado. Empuja la agarradera del cable hacia adelante y hacia arriba, extendiendo el brazo por completo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1266-6t00BsF.jpg', 'videos/1266-6t00BsF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0191', 'cable one arm lateral bent-over', 'chest', 'chest', 'cable', 'Stand with your feet shoulder-width apart, facing a cable machine. Grasp the handle with one hand and step back to create tension on the cable. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow. Slowly bring your arm back to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, frente a una máquina de cable. Sujeta la agarradera con una mano y retrocede un paso para crear tensión en el cable. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende el brazo hacia el lado, paralelo al suelo, con una ligera flexión en el codo. Regresa lentamente el brazo a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado, luego cambia de lado.', 'deltoids', '["deltoids","trapezius"]'::jsonb, 'pectorals', 'images/0191-dB07vDu.jpg', 'videos/0191-dB07vDu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0192', 'cable one arm lateral raise', 'shoulders', 'shoulders', 'cable', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable. Keep your arm straight and slowly raise it out to the side until it is parallel to the ground. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta la agarradera del cable con una mano, con la palma hacia abajo, y colócate lo suficientemente alejado de la máquina para que haya tensión en el cable. Mantén el brazo recto y levántalo lentamente hacia el lado hasta que quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'traps', '["traps","triceps"]'::jsonb, 'delts', 'images/0192-wEulIzp.jpg', 'videos/0192-wEulIzp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1633', 'cable one arm preacher curl', 'upper arms', 'upper arms', 'cable', 'Adjust the cable machine so that the preacher curl pad is at chest height. Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad. Keep your back straight and your core engaged. Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad. Pause for a moment at the top of the movement, squeezing your biceps. Slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions. Switch arms and repeat the exercise.', 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott. Mantén la espalda recta y el core activado. Curva lentamente la agarradera del cable hacia el hombro, manteniendo la parte superior del brazo contra la almohadilla. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1633-eHBlPsa.jpg', 'videos/1633-eHBlPsa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1267', 'cable one arm press on exercise ball', 'chest', 'chest', 'cable', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a cable handle in one hand and position your arm at chest height, elbow bent. Place your other hand on your hip for stability. Press the cable handle forward, extending your arm fully. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y coloca el brazo a la altura del pecho, con el codo flexionado. Coloca la otra mano en la cadera para mantener el equilibrio. Empuja la agarradera del cable hacia adelante, extendiendo el brazo por completo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1267-MKIelrR.jpg', 'videos/1267-MKIelrR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3563', 'cable one arm pulldown', 'back', 'back', 'cable', 'Attach a single handle to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with an overhand grip and extend your arm fully. Keep your back straight and your core engaged. Pull the handle down towards your side while keeping your elbow close to your body. Pause for a moment at the bottom of the movement, squeezing your lat muscle. Slowly release the handle back to the starting position. Repeat for the desired number of repetitions. Switch sides and repeat the exercise with the other arm.', 'Sujeta una agarradera individual a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera con un agarre prono y extiende el brazo por completo. Mantén la espalda recta y el core activado. Jala la agarradera hacia abajo en dirección al costado, manteniendo el codo cerca del cuerpo. Haz una pausa por un momento en la parte baja del movimiento, apretando el dorsal. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el otro brazo.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/3563-U5INZY6.jpg', 'videos/3563-U5INZY6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1635', 'cable one arm reverse preacher curl', 'upper arms', 'upper arms', 'cable', 'Adjust the cable machine so that the pulley is at the lowest position. Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad. Keep your back straight and your core engaged throughout the exercise. Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad. Pause for a moment at the top of the movement, squeezing your bicep. Slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions. Switch arms and repeat the exercise.', 'Ajusta la máquina de cable de modo que la polea quede en la posición más baja. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott. Mantén la espalda recta y el core activado durante todo el ejercicio. Curva lentamente el antebrazo hacia el bíceps, manteniendo la parte superior del brazo inmóvil contra la almohadilla. Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1635-ZXnjcOQ.jpg', 'videos/1635-ZXnjcOQ.gif');
